import { useState, useEffect, useCallback } from 'react';
import { Trash2, X } from 'lucide-react';
import '../pages/Hosts.css';
import { confirmAction, notifyAction } from './confirmUtils';

type AgentConnectivityModalProps = {
  onClose: () => void;
};

export function AgentConnectivityModal({ onClose }: AgentConnectivityModalProps) {
  const [hosts, setHosts] = useState<Record<string, unknown>[]>([]);
  const [selectedPendingIds, setSelectedPendingIds] = useState<Record<string, boolean>>({});
  const [connectingAgents, setConnectingAgents] = useState(false);

  const fetchHosts = useCallback(async () => {
    try {
      const res = await fetch('/api/v1/ui/hosts');
      if (res.ok) setHosts(await res.json());
    } catch (e) {
      console.error(e);
    }
  }, []);

  useEffect(() => {
    void (async () => { await fetchHosts(); })();
    const t = setInterval(() => { void (async () => { await fetchHosts(); })(); }, 5000);
    return () => clearInterval(t);
  }, [fetchHosts]);

  const deleteHost = async (id: string) => {
    if (!(await confirmAction('Disconnect this node? It will move back to discovered nodes and can be connected again.'))) return;
    try {
      const res = await fetch(`/api/v1/ui/hosts/${id}`, { method: 'DELETE' });
      if (res.ok) {
        fetchHosts();
      } else {
        const errorData = await res.json().catch(() => ({}));
        notifyAction(errorData.message || 'Failed to disconnect node.');
      }
    } catch (e) {
      console.error(e);
      notifyAction('An error occurred while disconnecting the node.');
    }
  };

  const parseIpList = (raw: unknown): string[] => {
    if (Array.isArray(raw)) return raw.map(String).map(ip => ip.trim()).filter(Boolean);
    if (typeof raw === 'string' && raw.startsWith('[')) {
      try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed.map(String).map(ip => ip.trim()).filter(Boolean);
      } catch { /* ignore */ }
    }
    if (typeof raw === 'string') return raw.split(',').map(ip => ip.trim()).filter(Boolean);
    return [];
  };

  const displayIp = (raw: unknown) => {
    const ips = parseIpList(raw);
    return ips.find(ip => ip.startsWith('192.168.'))
      || ips.find(ip => !ip.startsWith('127.') && !ip.startsWith('172.'))
      || ips[0]
      || 'Unknown';
  };

  const activeHosts = hosts.filter(h => h.status !== 'PENDING');
  const activeHostIps = new Set(activeHosts.map(host => displayIp(host.ipAddresses)));
  const pendingHosts = Array.from(
    hosts
      .filter(h => h.status === 'PENDING' && !activeHostIps.has(displayIp(h.ipAddresses)))
      .reduce<Map<string, Record<string, unknown>>>((byIp, host) => {
        const ip = displayIp(host.ipAddresses);
        const existing = byIp.get(ip);
        const heartbeat = Date.parse((host as any).lastHeartbeat || '') || 0;
        const existingHeartbeat = Date.parse((existing as any)?.lastHeartbeat || '') || 0;
        const expectedSuffix = `-${ip.split('.').pop()}`;
        const isCanonicalId = String(host.id || '').endsWith(expectedSuffix);
        const existingIsCanonicalId = String(existing?.id || '').endsWith(expectedSuffix);

        if (
          !existing
          || (isCanonicalId && !existingIsCanonicalId)
          || (isCanonicalId === existingIsCanonicalId && heartbeat > existingHeartbeat)
        ) {
          byIp.set(ip, host);
        }
        return byIp;
      }, new Map<string, Record<string, unknown>>())
      .values(),
  );
  const selectedCount = pendingHosts.filter(host => selectedPendingIds[String(host.id)]).length;
  const allPendingSelected = pendingHosts.length > 0 && selectedCount === pendingHosts.length;

  const togglePendingHost = (id: string) => {
    setSelectedPendingIds(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleAllPendingHosts = () => {
    if (allPendingSelected) {
      setSelectedPendingIds({});
      return;
    }
    setSelectedPendingIds(Object.fromEntries(pendingHosts.map(host => [String(host.id), true])));
  };

  const connectSelectedAgents = async () => {
    const selectedIds = pendingHosts.filter(host => selectedPendingIds[String(host.id)]).map(host => host.id);
    if (selectedIds.length === 0) return;
    setConnectingAgents(true);
    try {
      const results = await Promise.allSettled(
        selectedIds.map(id => fetch(`/api/v1/ui/hosts/${id}/approve`, { method: 'POST' }))
      );
      const failed = results.filter(result => result.status === 'rejected'
        || (result.status === 'fulfilled' && !result.value.ok)).length;
      if (failed > 0) {
        notifyAction(`${failed} agent${failed === 1 ? '' : 's'} could not be connected. Refreshing the list now.`);
      }
      setSelectedPendingIds({});
      await fetchHosts();
    } finally {
      setConnectingAgents(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose} style={{ zIndex: 9999 }}>
      <div className="modal" onClick={e => e.stopPropagation()} style={{ padding: 0, overflow: 'hidden', maxWidth: '720px' }}>
        <div className="modal-header" style={{ padding: '24px 32px 16px 32px', margin: 0, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ fontSize: '1.25rem', fontWeight: 500, color: '#111827', margin: 0 }}>Agent Connectivity</h2>
          <button className="modal-close" onClick={onClose} style={{ border: 'none', background: 'transparent', padding: 0, color: '#9CA3AF' }}>
            <X size={20} />
          </button>
        </div>

        {/* Separator line below header */}
        <div style={{ height: '1px', background: '#F1F5F9', margin: '0 0 0 0' }} />

        <div style={{ padding: '20px 32px 8px 32px' }}>
          {pendingHosts.length === 0 ? (
            <div className="empty-pending">
              No new nodes discovered. Run the agent script on a VM to discover it.
            </div>
          ) : (
            <div>
              {/* Section label row */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                <span style={{ fontSize: '11px', color: '#94A3B8', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.07em' }}>
                  Discovered Nodes
                </span>
                <label style={{ display: 'flex', alignItems: 'center', gap: '8px', margin: 0, cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={allPendingSelected}
                    onChange={toggleAllPendingHosts}
                    style={{ width: '16px', height: '16px', accentColor: '#8B5CF6', cursor: 'pointer' }}
                  />
                  <span style={{ fontSize: '13px', color: '#1E293B', fontWeight: 500 }}>Select all</span>
                </label>
              </div>

              {/* Node cards inside grey container */}
              <div style={{ background: '#F8FAFC', borderRadius: '10px', padding: '12px', display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '360px', overflowY: 'auto' }}>
                {pendingHosts.map(host => (
                  <div
                    key={String(host.id)}
                    onClick={() => togglePendingHost(String(host.id))}
                    style={{
                      background: '#FFFFFF',
                      border: selectedPendingIds[String(host.id)] ? '1.5px solid #8B5CF6' : '1px solid #E2E8F0',
                      borderRadius: '8px',
                      padding: '12px 14px',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '12px',
                      cursor: 'pointer',
                      boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
                    }}
                  >
                    <label onClick={e => e.stopPropagation()} style={{ margin: 0, display: 'flex', flexShrink: 0 }}>
                      <input
                        type="checkbox"
                        checked={!!selectedPendingIds[String(host.id)]}
                        onChange={() => togglePendingHost(String(host.id))}
                        style={{ width: '16px', height: '16px', accentColor: '#8B5CF6', cursor: 'pointer' }}
                      />
                    </label>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ fontSize: '14px', color: '#1E293B', fontWeight: 500, margin: '0 0 2px 0' }}>{(host as any).agentName || (host as any).hostname}</p>
                      <p style={{ fontSize: '12px', color: '#94A3B8', margin: 0 }}>{displayIp(host.ipAddresses)} &nbsp;┬╖&nbsp; {(host as any).agentPath || 'Path unavailable'}</p>
                    </div>
                    <button
                      title="Reject & remove"
                      onClick={e => { e.stopPropagation(); deleteHost(String(host.id)); }}
                      style={{ border: 'none', background: 'transparent', color: '#CBD5E1', padding: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', flexShrink: 0 }}
                      onMouseEnter={e => (e.currentTarget.style.color = '#EF4444')}
                      onMouseLeave={e => (e.currentTarget.style.color = '#CBD5E1')}
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="modal-footer" style={{ margin: '0', borderTop: '1px solid #F1F5F9', padding: '20px 32px', display: 'flex', justifyContent: 'flex-end', gap: '12px', background: '#FFFFFF' }}>
          <button 
            className="btn" 
            onClick={onClose} 
            style={{ background: '#FFFFFF', border: '1px solid #CBD5E1', color: '#64748B', padding: '8px 24px', borderRadius: '8px', fontWeight: 500, fontSize: '14px' }}
          >
            Cancel
          </button>
          <button 
            className="btn btn-primary-action" 
            disabled={selectedCount === 0 || connectingAgents} 
            onClick={connectSelectedAgents} 
            style={{ 
              background: '#FFFFFF', 
              border: '1px solid #8B5CF6', 
              color: '#8B5CF6', 
              padding: '8px 24px', 
              borderRadius: '8px', 
              fontWeight: 500, 
              fontSize: '14px',
              opacity: (selectedCount === 0 || connectingAgents) ? 0.5 : 1
            }}
          >
            {connectingAgents ? 'Connecting...' : 'Connect'}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { type ConfirmRequest, CONFIRM_EVENT } from './confirmUtils';
import { X } from 'lucide-react';
import orangeBanner from '../assets/orange.png';
import './ConfirmDialog.css';

export function GlobalConfirmDialog() {
  const [request, setRequest] = useState<ConfirmRequest | null>(null);
  const confirmButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const handleRequest = (event: Event) => {
      setRequest((event as CustomEvent<ConfirmRequest>).detail);
    };
    window.addEventListener(CONFIRM_EVENT, handleRequest);
    return () => window.removeEventListener(CONFIRM_EVENT, handleRequest);
  }, [finish]);

  const finishRef = useRef<((c: boolean) => void) | null>(null);
  const finish = useCallback((confirmed: boolean) => {
    if (!request) return;
    request.resolve?.(confirmed);
    setRequest(null);
  }, [request]);

  useEffect(() => {
    if (!request) return;
    confirmButtonRef.current?.focus();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') finish(false);
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [request, finish]);

  if (!request) return null;

  return (
    <div className="app-confirm-backdrop" onMouseDown={() => finish(false)}>
      <section
        className="app-confirm-dialog"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="app-confirm-title"
        aria-describedby="app-confirm-message"
        onMouseDown={event => event.stopPropagation()}
      >
        <div className="app-confirm-banner">
          <img src={orangeBanner} alt="" aria-hidden="true" />
          <button type="button" onClick={() => finish(false)} aria-label="Close confirmation">
            <X size={20} />
          </button>
        </div>
        <div className="app-confirm-content">
          <h2 id="app-confirm-title">{request.title || 'Please confirm'}</h2>
          <p id="app-confirm-message">{request.message}</p>
          <div className="app-confirm-actions">
            {request.showCancel !== false && (
              <button type="button" className="app-confirm-cancel" onClick={() => finish(false)}>Cancel</button>
            )}
            <button ref={confirmButtonRef} type="button" className="app-confirm-primary" onClick={() => finish(true)}>
              {request.confirmLabel || 'OK'}
            </button>
          </div>
        </div>
      </section>
    </div>
  );
}

import { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  Bell,
  ChevronDown,
  ChevronRight,
  LayoutDashboard,
  LineChart,
  Network,
  Package,
  PlayCircle,
  Server,
  Settings,
  ShieldAlert,
  Users,
} from 'lucide-react';
import './Sidebar.css';
import collapseIcon from '../assets/collapse.png';

type NavItem = {
  icon?: React.ReactNode;
  label: string;
  path?: string;
  subItems?: NavItem[];
};

type NavSection = {
  label: string;
  items: NavItem[];
};

const navSections: NavSection[] = [
  {
    label: '',
    items: [
      { icon: LayoutDashboard as React.ElementType as React.ElementType, label: 'Dashboard', path: '/dashboard' },
      { icon: Package as React.ElementType as React.ElementType, label: 'Artifacts', path: '/artifacts' },
      { icon: Network as React.ElementType as React.ElementType, label: 'Cluster', path: '/clusters' },
      { icon: Server as React.ElementType as React.ElementType, label: 'Hosts', path: '/hosts' },
      { icon: LineChart as React.ElementType as React.ElementType, label: 'Monitoring', path: '/monitoring' },
      { icon: Bell as React.ElementType as React.ElementType, label: 'Alerts', path: '/alerts' },
      { icon: ShieldAlert as React.ElementType as React.ElementType, label: 'Audits', path: '/audit' },
      { icon: PlayCircle as React.ElementType as React.ElementType, label: 'Jobs', path: '/jobs' },
      { icon: Settings as React.ElementType as React.ElementType, label: 'LDAP', path: '/ldap-settings' },
      { icon: Users as React.ElementType as React.ElementType, label: 'User Management', path: '/user-management' },
    ],
  },
];

const hiddenNavPaths = new Set(['/user-management', '/commands', '/ldap-settings', '/admin']);

export function Sidebar() {
  const [isCollapsed, setIsCollapsed] = useState(() => {
    return localStorage.getItem('tantor.sidebarCollapsed') === 'true';
  });

  const toggleCollapse = () => {
    setIsCollapsed(prev => {
      const next = !prev;
      localStorage.setItem('tantor.sidebarCollapsed', String(next));
      return next;
    });
  };

  const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>({
    Clusters: true,
  });
  const location = useLocation();

  const toggleExpand = (label: string) => {
    setExpandedItems(prev => ({ ...prev, [label]: !prev[label] }));
  };

  const renderItem = (item: NavItem, depth = 0) => {
    if (item.subItems) {
      const isExpanded = expandedItems[item.label];
      const isActive = item.subItems.some(sub => location.pathname === sub.path || (sub.path && sub.path !== '/' && location.pathname.startsWith(sub.path + '/')));

      return (
        <div key={item.label} className="nav-item-group">
          <div
            className={`nav-item ${isActive ? 'active-parent' : ''}`}
            style={{ paddingLeft: isCollapsed ? '0px' : `${18 + depth * 12}px` }}
            onClick={() => toggleExpand(item.label)}
          >
            {item.icon && ((item.icon as any)({ size: 15, className: 'nav-item-icon' }))}
            <span style={{ flex: 1 }}>{item.label}</span>
            {!isCollapsed && (isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />)}
          </div>
          {!isCollapsed && isExpanded && (
            <div className="nav-subitems">
              {item.subItems.map(sub => renderItem(sub, depth + 1))}
            </div>
          )}
        </div>
      );
    }

    return (
      <NavLink
        key={item.label}
        to={item.path!}
        end={item.path === '/dashboard'}
        className={({ isActive }) => `nav-item${isActive ? ' active' : ''}`}
      >
        {item.icon && ((item.icon as any)({ size: 20, className: 'nav-item-icon' }))}
        {!item.icon && <span className="nav-item-dot" />}
        <span>{item.label}</span>
      </NavLink>
    );
  };

  return (
    <aside className={`sidebar ${isCollapsed ? 'collapsed' : ''}`}>
      <nav className="sidebar-nav">
        {navSections.map(section => (
          <div key={section.label} className="nav-section">
            {section.label && <span className="nav-section-label">{section.label}</span>}
            {section.items
              .filter(item => !item.path || !hiddenNavPaths.has(item.path))
              .map(item => renderItem(item))}
          </div>
        ))}
      </nav>

      <div className="sidebar-footer">
        <img
          src={collapseIcon}
          alt="Collapse Sidebar"
          className="sidebar-toggle-icon"
          onClick={toggleCollapse}
          style={{ transform: isCollapsed ? 'rotate(180deg)' : 'none' }}
        />
      </div>
    </aside>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import {
  Upload, XCircle, ChevronDown, ChevronUp,
  Loader2, X, RefreshCw, Server, DownloadCloud,
  Power, PowerOff, Trash2, AlertTriangle, MoreVertical, FileText
} from 'lucide-react';
import { usePermissions } from '../hooks/usePermissions';
import { AnchoredMenu } from '../components/AnchoredMenu';
import './Artifacts.css';
import orangeBanner from '../assets/orange.png';

interface ArtifactVersion {
  id: string;
  service_type: string;
  version: string;
  available: boolean;
  release_date: string;
  size_mb: string;
  filename: string;
  sha256: string;
  download_url: string;
}

interface Host {
  id: string;
  hostname: string;
  status: string;
  agentStatus?: string;
  available?: boolean;
  ipAddress?: string;
  ipAddresses?: string;
}

interface HostParcel {
  id: string;
  hostId: string;
  hostIp?: string;
  parcelDir?: string;
  artifactId: string;
  serviceType: string;
  version: string;
  status: string;
  active: boolean;
  lastTaskId?: string;
  errorMsg?: string;
  updatedAt?: string;
}

type ParcelAction = 'distribute' | 'activate' | 'deactivate' | 'remove';

interface ArtifactAuditEvent {
  id: string;
  userName?: string;
  category?: string;
  action: string;
  resourceType?: string;
  artifactId?: string;
  status: string;
  details?: unknown;
  createdAt?: string;
}

const artifactServiceOptions = [
  {
    value: 'KAFKA',
    label: 'Apache Kafka',
    versionPlaceholder: 'e.g. 3.9.2',
    directoryPlaceholder: 'custom/kafka (under configured repository root)',
    fileLabel: 'Kafka parcel binary (.tgz or .tar.gz)',
    fileAccept: '.tgz,.tar.gz',
    helper: 'Kafka binaries appear in the parcel list and can be distributed to hosts.',
  },
  {
    value: 'KAFKA_EXPORTER',
    label: 'Kafka Exporter',
    versionPlaceholder: 'e.g. 1.9.0',
    directoryPlaceholder: 'custom/kafka-exporter (under configured repository root)',
    fileLabel: 'Kafka exporter binary (.tar.gz)',
    fileAccept: '.tgz,.tar.gz',
    helper: 'Kafka exporter binaries for metrics collection.',
  },
  {
    value: 'JMX_EXPORTER',
    label: 'JMX Exporter',
    versionPlaceholder: 'e.g. 0.20.0',
    directoryPlaceholder: 'custom/jmx-exporter (under configured repository root)',
    fileLabel: 'JMX exporter jar (.jar)',
    fileAccept: '.jar',
    helper: 'JMX exporter jars are stored for Kafka monitoring deployments.',
  },
];

const artifactServiceLabels: Record<string, string> = {
  KAFKA: 'Kafka',
  KAFKA_EXPORTER: 'Kafka Exporter',
  JMX_EXPORTER: 'JMX Exporter',
};

const artifactServiceLabel = (serviceType: string) =>
  artifactServiceLabels[serviceType] || serviceType
    .toLowerCase()
    .split('_')
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');

export function Artifacts() {
  const { canManage } = usePermissions();
  const [versions, setVersions] = useState<ArtifactVersion[]>([]);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [hostParcels, setHostParcels] = useState<HostParcel[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [actingKey, setActingKey] = useState<string | null>(null);
  const [uploadMsg, setUploadMsg] = useState<{ text: string; ok: boolean } | null>(null);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [serviceType, setServiceType] = useState('KAFKA');
  const [versionInput, setVersionInput] = useState('');
  const [uploadDirectory, setUploadDirectory] = useState('');
  const [universalDistributionDir, setUniversalDistributionDir] = useState(
    () => window.localStorage.getItem('tantor.universalDistributionDir') || '/srv/apps/tantor/parcels',
  );
  const [distributionDirs, setDistributionDirs] = useState<Record<string, string>>({});
  const [hostDistributionDirs, setHostDistributionDirs] = useState<Record<string, string>>({});
  const [selectedHosts, setSelectedHosts] = useState<Record<string, string[]>>({});
  const [openArtifactMenuId, setOpenArtifactMenuId] = useState<string | null>(null);
  const [artifactMenuAnchor, setArtifactMenuAnchor] = useState<HTMLElement | null>(null);
  const [auditModalArtifact, setAuditModalArtifact] = useState<ArtifactVersion | null>(null);
  const [artifactAuditEvents, setArtifactAuditEvents] = useState<ArtifactAuditEvent[]>([]);
  const [artifactAuditLoading, setArtifactAuditLoading] = useState(false);
  const [deleteConfirmVer, setDeleteConfirmVer] = useState<ArtifactVersion | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const selectedServiceOption = artifactServiceOptions.find(option => option.value === serviceType) || artifactServiceOptions[0];
  const fileMatchesServiceType = !file || selectedServiceOption.fileAccept
    .split(',')
    .some(extension => file.name.toLowerCase().endsWith(extension.trim().toLowerCase()));

  const fetchVersions = useCallback(async () => {
    const res = await fetch('/api/v1/artifacts?status=AVAILABLE&size=100');
    if (!res.ok) return;
    const data = await res.json();
    setVersions((data.content || []).map((a: ArtifactVersion) => ({
      id: a.id,
      service_type: (a.serviceType || 'KAFKA').toUpperCase(),
      version: a.version,
      available: a.status === 'AVAILABLE',
      release_date: a.createdAt ? new Date(a.createdAt).toLocaleDateString() : '',
      size_mb: (a.fileSizeBytes / 1024 / 1024).toFixed(1),
      filename: a.fileName,
      sha256: a.sha256,
      download_url: a.downloadUrl || `/api/v1/artifacts/${a.id}/download`,
    })));
  }, []);

  const fetchHosts = useCallback(async () => {
    const res = await fetch('/api/v1/ui/hosts');
    if (!res.ok) return;
    setHosts(await res.json());
  }, []);

  const fetchParcelState = useCallback(async () => {
    const res = await fetch('/api/v1/ui/parcels');
    if (!res.ok) return;
    setHostParcels(await res.json());
  }, []);

  const refreshAll = useCallback(async () => {
    setLoading(true);
    try {
      await Promise.all([fetchVersions(), fetchHosts(), fetchParcelState()]);
    } catch (e: any) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [fetchVersions, fetchHosts, fetchParcelState]);

  useEffect(() => {
    void (async () => { await refreshAll(); })();
    const timer = window.setInterval(() => { void (async () => { await fetchParcelState(); })(); }, 5000);
    return () => window.clearInterval(timer);
  }, [refreshAll, fetchParcelState]);

  useEffect(() => {
    window.localStorage.setItem('tantor.universalDistributionDir', universalDistributionDir);
  }, [universalDistributionDir]);

  const handleUploadSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManage) return;
    if (!file || !versionInput || !fileMatchesServiceType) return;
    setUploading(true);
    setUploadMsg(null);

    const form = new FormData();
    form.append('file', file);
    form.append('serviceType', serviceType);
    form.append('version', versionInput);
    if (uploadDirectory.trim()) form.append('storageDirectory', uploadDirectory.trim());
    form.append('overwrite', 'false');

    try {
      const res = await fetch('/api/v1/artifacts', { method: 'POST', body: form });
      if (res.ok) {
        setUploadMsg({ text: `Uploaded ${file.name} (${(file.size / 1024 / 1024).toFixed(1)} MB)`, ok: true });
        setShowUploadModal(false);
        setFile(null);
        setVersionInput('');
        setUploadDirectory('');
        await refreshAll();
      } else {
        const err = await res.json().catch(() => ({}));
        setUploadMsg({ text: err.detail || err.message || 'Upload failed.', ok: false });
      }
    } catch {
      setUploadMsg({ text: 'Upload failed due to a network error.', ok: false });
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const getHostParcel = (artifactId: string, hostId: string) =>
    hostParcels.find(p => p.artifactId === artifactId && p.hostId === hostId);

  const isHostOnline = (host: Host) => {
    const status = (host.status || '').toUpperCase();
    const agentStatus = (host.agentStatus || '').toUpperCase();
    return agentStatus === 'ONLINE' || status === 'ONLINE' || status === 'AVAILABLE';
  };

  const runParcelAction = async (action: ParcelAction, ver: ArtifactVersion, host: Host) => {
    if (!canManage) return;
    const key = `${action}-${ver.id}-${host.id}`;
    setActingKey(key);
    setUploadMsg(null);
    try {
      const res = await fetch(`/api/v1/ui/parcels/${ver.id}/${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          hostIds: [host.id],
          checksum: ver.sha256,
          serviceType: ver.service_type,
          version: ver.version,
          fileName: ver.filename,
          parcelDir: hostDistributionDirs[`${ver.id}:${host.id}`] || distributionDirs[ver.id] || universalDistributionDir,
        }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || err.error || `${action} failed`);
      }
      await fetchParcelState();
      setUploadMsg({ text: `${actionLabel(action)} scheduled on ${host.hostname || host.id}`, ok: true });
    } catch (e: unknown) {
      setUploadMsg({ text: e.message || `${actionLabel(action)} failed`, ok: false });
    } finally {
      setActingKey(null);
    }
  };

  const distributeAll = async (ver: ArtifactVersion) => {
    if (!canManage) return;
    const eligible = hosts.filter(host =>
      isHostOnline(host)
      && (() => {
        const state = getHostParcel(ver.id, host.id);
        return !state || ['FAILED', 'REMOVED'].includes(state.status);
      })()
    );
    if (eligible.length === 0) {
      setUploadMsg({ text: 'No online hosts are waiting for this parcel.', ok: false });
      return;
    }
    const key = `distribute-all-${ver.id}`;
    setActingKey(key);
    try {
      const res = await fetch(`/api/v1/ui/parcels/${ver.id}/distribute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          hostIds: eligible.map(host => host.id),
          checksum: ver.sha256,
          serviceType: ver.service_type,
          version: ver.version,
          fileName: ver.filename,
          parcelDir: distributionDirs[ver.id] || universalDistributionDir,
          parcelDirs: Object.fromEntries(eligible.map(host => [
            host.id,
            hostDistributionDirs[`${ver.id}:${host.id}`] || distributionDirs[ver.id] || universalDistributionDir,
          ])),
        }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.message || body.error || 'Distribute all failed.');
      }
      setUploadMsg({ text: `Distribution scheduled on ${eligible.length} hosts.`, ok: true });
      await fetchParcelState();
    } catch (e: unknown) {
      setUploadMsg({ text: e.message || 'Distribute all failed.', ok: false });
    } finally {
      setActingKey(null);
    }
  };

  const distributeSelected = async (ver: ArtifactVersion) => {
    if (!canManage) return;
    const ids = selectedHosts[ver.id] || [];
    const targets = hosts.filter(host => ids.includes(host.id));
    if (!targets.length) {
      setUploadMsg({ text: 'Select at least one host.', ok: false });
      return;
    }
    const key = `distribute-selected-${ver.id}`;
    setActingKey(key);
    try {
      const res = await fetch(`/api/v1/ui/parcels/${ver.id}/distribute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          hostIds: targets.map(host => host.id),
          checksum: ver.sha256,
          serviceType: ver.service_type,
          version: ver.version,
          fileName: ver.filename,
          parcelDir: distributionDirs[ver.id] || universalDistributionDir,
          parcelDirs: Object.fromEntries(targets.map(host => [
            host.id,
            hostDistributionDirs[`${ver.id}:${host.id}`] || distributionDirs[ver.id] || universalDistributionDir,
          ])),
        }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.message || body.error || 'Selected-host distribution failed.');
      }
      setUploadMsg({ text: `Distribution scheduled on ${targets.length} selected host${targets.length === 1 ? '' : 's'}.`, ok: true });
      setSelectedHosts(current => ({ ...current, [ver.id]: [] }));
      await fetchParcelState();
    } catch (e: unknown) {
      setUploadMsg({ text: e.message || 'Selected-host distribution failed.', ok: false });
    } finally {
      setActingKey(null);
    }
  };

  const toggleHostSelection = (artifactId: string, hostId: string) => {
    if (!canManage) return;
    setSelectedHosts(current => {
      const selected = current[artifactId] || [];
      return {
        ...current, [artifactId]: selected.includes(hostId)
          ? selected.filter(id => id !== hostId)
          : [...selected, hostId]
      };
    });
  };

  const deleteArtifactBinary = (ver: ArtifactVersion) => {
    if (!canManage) return;
    setOpenArtifactMenuId(null);
    const inUse = hostParcels.some(p => p.artifactId === ver.id && p.status !== 'REMOVED');
    if (inUse) {
      setUploadMsg({
        text: `Remove ${artifactServiceLabel(ver.service_type)} ${ver.version} from all hosts before deleting the binary.`,
        ok: false,
      });
      return;
    }
    setDeleteConfirmVer(ver);
  };

  const confirmDeleteArtifactBinary = async (ver: ArtifactVersion) => {
    const key = `delete-artifact-${ver.id}`;
    setActingKey(key);
    setUploadMsg(null);
    setDeleteConfirmVer(null);
    try {
      const res = await fetch(`/api/v1/artifacts/${ver.id}`, {
        method: 'DELETE',
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.detail || err.message || err.error || 'Delete failed.');
      }
      if (expanded === ver.id) setExpanded(null);
      setUploadMsg({ text: `Deleted ${artifactServiceLabel(ver.service_type)} ${ver.version} binary.`, ok: true });
      await refreshAll();
    } catch (e: unknown) {
      setUploadMsg({ text: e.message || 'Delete failed.', ok: false });
    } finally {
      setActingKey(null);
    }
  };

  const openArtifactLogs = async (ver: ArtifactVersion) => {
    setOpenArtifactMenuId(null);
    setAuditModalArtifact(ver);
    setArtifactAuditEvents([]);
    setArtifactAuditLoading(true);
    try {
      const res = await fetch(`/api/v1/artifacts/audit/${ver.id}`);
      if (!res.ok) throw new Error('Unable to load artifact logs.');
      const body = await res.json();
      setArtifactAuditEvents(body.events || []);
    } catch (e: unknown) {
      setUploadMsg({ text: e.message || 'Unable to load artifact logs.', ok: false });
    } finally {
      setArtifactAuditLoading(false);
    }
  };

  const actionButton = (action: ParcelAction, ver: ArtifactVersion, host: Host, disabled = false) => {
    const key = `${action}-${ver.id}-${host.id}`;
    const Icon = actionIcon(action);
    return (
      <button
        key={action}
        className={`parcel-action ${action}`}
        disabled={disabled || actingKey !== null || !canManage}
        onClick={() => runParcelAction(action, ver, host)}
        title={actionLabel(action)}
      >
        {actingKey === key ? <Loader2 size={13} className="spin" /> : <Icon size={13} />}
        {actionLabel(action)}
      </button>
    );
  };

  const formatParcelStatus = (status?: string) => {
    if (!status || status === 'AVAILABLE') return 'Available';
    return status
      .toLowerCase()
      .split('_')
      .map(part => part.charAt(0).toUpperCase() + part.slice(1))
      .join(' ');
  };

  const renderActions = (ver: ArtifactVersion, host: Host, state?: HostParcel) => {
    if (!canManage) {
      return <span className="parcel-blocked">View only</span>;
    }
    const hostOnline = isHostOnline(host);
    if (!hostOnline) {
      return (
        <span className="parcel-blocked">
          <AlertTriangle size={13} />
          Host offline
        </span>
      );
    }
    if (!ver.available) {
      return (
        <span className="parcel-blocked">
          <XCircle size={13} />
          Artifact unavailable
        </span>
      );
    }
    const status = state?.status || 'AVAILABLE';
    if (['DISTRIBUTING', 'ACTIVATING', 'DEACTIVATING', 'REMOVING'].includes(status)) {
      const displayLabel = status === 'DISTRIBUTING' ? 'Distributing' :
        status === 'ACTIVATING' ? 'Activating' :
          status === 'DEACTIVATING' ? 'Deactivating' : 'Removing';
      return (
        <button className={`parcel-action progress ${status.toLowerCase()}`} disabled>
          <Loader2 size={13} className="spin" />
          {displayLabel}
        </button>
      );
    }
    if (!state || status === 'REMOVED') {
      return actionButton('distribute', ver, host);
    }
    if (status === 'FAILED') {
      return (
        <>
          {actionButton('distribute', ver, host)}
          {actionButton('remove', ver, host)}
        </>
      );
    }
    if (status === 'ACTIVE') {
      return actionButton('deactivate', ver, host);
    }
    return (
      <>
        {actionButton('activate', ver, host)}
        {actionButton('remove', ver, host)}
      </>
    );
  };

  return (
    <div className="artifacts-page animate-fade-in" onClick={() => { setOpenArtifactMenuId(null); setArtifactMenuAnchor(null); }}>
      <header className="page-header flex-between">
        <div>
          <h1>Artifacts</h1>
          <p>Manage your Linux sDistribute, activate, deactivate, and remove Kafka parcels on managed hostservers for Kafka deployment</p>
        </div>
        <div className="header-actions">
          {uploadMsg && (
            <span className={`upload-msg ${uploadMsg.ok ? 'ok' : 'err'}`}>
              {uploadMsg.text}
            </span>
          )}
          <button className="btn btn-sync" onClick={refreshAll} disabled={loading || actingKey !== null}>
            <RefreshCw size={14} className={loading ? 'spin' : ''} />
            Sync
          </button>
          {canManage && (
            <button className="btn btn-primary-action" onClick={() => setShowUploadModal(true)} disabled={uploading}>
              {uploading ? <Loader2 size={14} className="spin" /> : <Upload size={14} />}
              Upload binary
            </button>
          )}
        </div>
      </header>

      <section className="universal-distribution-directory">
        <label>Universal distribution directory</label>
        <input
          className="form-control"
          value={universalDistributionDir}
          onChange={event => setUniversalDistributionDir(event.target.value)}
          placeholder="/srv/apps/tantor/parcels"
          disabled={!canManage}
        />
      </section>

      {loading ? (
        <div className="state-center">
          <Loader2 size={28} className="spin" />
          <p>Loading parcels...</p>
        </div>
      ) : versions.length === 0 ? (
        <div className="state-center no-artifacts">
          <div className="no-artifacts-illustration-container">
            <svg className="no-artifacts-illustration" width="130" height="100" viewBox="0 0 130 100" fill="none" xmlns="http://www.w3.org/2000/svg">
              {/* Card 1 */}
              <rect x="15" y="10" width="100" height="20" rx="4" fill="white" stroke="#E2E8F0" strokeWidth="1" />
              <rect x="25" y="18" width="20" height="4" rx="1" fill="#A78BFA" opacity="0.6" />
              <rect x="55" y="18" width="20" height="4" rx="1" fill="#A78BFA" opacity="0.6" />
              {/* Card 2 */}
              <rect x="15" y="36" width="100" height="20" rx="4" fill="white" stroke="#D1D5DB" strokeWidth="1.2" />
              <rect x="25" y="44" width="24" height="4" rx="1" fill="#8B5CF6" opacity="0.8" />
              <rect x="57" y="44" width="24" height="4" rx="1" fill="#8B5CF6" opacity="0.8" />
              {/* Card 3 */}
              <rect x="15" y="62" width="100" height="20" rx="4" fill="white" stroke="#E2E8F0" strokeWidth="1" />
              <rect x="25" y="70" width="20" height="4" rx="1" fill="#A78BFA" opacity="0.6" />
              <rect x="55" y="70" width="20" height="4" rx="1" fill="#A78BFA" opacity="0.6" />
              {/* Reflection lines under cards */}
              <line x1="25" y1="90" x2="45" y2="90" stroke="#E5E7EB" strokeWidth="1.5" strokeLinecap="round" />
              <line x1="55" y1="90" x2="75" y2="90" stroke="#E5E7EB" strokeWidth="1.5" strokeLinecap="round" />
              <line x1="85" y1="90" x2="105" y2="90" stroke="#E5E7EB" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </div>
          <h3>No Artifacts</h3>
          <p>Upload your first artifact to distribute and manage resources across hosts.</p>
        </div>
      ) : (
        <div className="artifacts-list-container">
          <h3 className="section-title">Artifact List</h3>
          <div className="versions-list">
            {versions.map(ver => {
              const isKafkaArtifact = ver.service_type === 'KAFKA';
              const isOpen = isKafkaArtifact && expanded === ver.id;
              const distributed = hostParcels.filter(p => p.artifactId === ver.id && p.status !== 'REMOVED').length;
              const active = hostParcels.filter(p => p.artifactId === ver.id && p.active).length;
              const deleteKey = `delete-artifact-${ver.id}`;
              const canDeleteBinary = distributed === 0 && active === 0;
              return (
                <div key={ver.id} className="version-card">
                  <div className="version-card-top">
                    <button
                      className={`version-card-header ${isKafkaArtifact ? '' : 'non-expandable'}`}
                      onClick={() => {
                        if (isKafkaArtifact) setExpanded(isOpen ? null : ver.id);
                      }}
                    >
                      <div className="status-dot-container">
                        <span className={`status-dot ${ver.available ? 'available' : 'unavailable'}`}></span>
                      </div>
                      <div className="version-info">
                        <div className="version-title-row">
                          <span className="version-name">{artifactServiceLabel(ver.service_type)} {ver.version}</span>
                          {ver.available ? (
                            <span className="status-badge available">Available</span>
                          ) : (
                            <span className="status-badge unavailable">Not downloaded</span>
                          )}
                          {active > 0 && <span className="status-badge active">Active on {active}</span>}
                        </div>
                        <div className="version-meta">
                          <span>Uploaded: {ver.release_date || 'N/A'}</span>
                          <span className="meta-separator">|</span>
                          <span>Size: {ver.size_mb} MB</span>
                          <span className="meta-separator">|</span>
                          <span className="meta-filename">File: {ver.filename}</span>
                        </div>
                      </div>
                    </button>
                    <div className="version-card-tools">
                      <div className="artifact-menu-anchor" onClick={event => event.stopPropagation()}>
                        <button
                          className="artifact-menu-button"
                          onClick={event => {
                            const opening = openArtifactMenuId !== ver.id;
                            setOpenArtifactMenuId(opening ? ver.id : null);
                            setArtifactMenuAnchor(opening ? event.currentTarget : null);
                          }}
                          title="Artifact actions"
                        >
                          <MoreVertical size={15} />
                        </button>
                        {openArtifactMenuId === ver.id && artifactMenuAnchor && (
                          <AnchoredMenu anchor={artifactMenuAnchor} className="artifact-action-menu" onClose={() => { setOpenArtifactMenuId(null); setArtifactMenuAnchor(null); }}>
                            <button onClick={() => openArtifactLogs(ver)}>
                              <FileText size={14} />
                              View Log
                            </button>
                            {canManage && (
                              <button
                                className="menu-item-delete"
                                disabled={!canDeleteBinary || actingKey !== null}
                                onClick={() => deleteArtifactBinary(ver)}
                                title={canDeleteBinary ? 'Delete uploaded binary' : 'Remove from all hosts before deleting binary'}
                              >
                                {actingKey === deleteKey ? <Loader2 size={14} className="spin" /> : <Trash2 size={14} />}
                                Delete
                              </button>
                            )}
                          </AnchoredMenu>
                        )}
                      </div>
                      {isKafkaArtifact && (
                        <div className="chevron-box" onClick={() => setExpanded(isOpen ? null : ver.id)}>
                          <span className="chevron">{isOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {isKafkaArtifact && isOpen && (
                    <div className="version-card-body">
                      {canManage && (
                        <div className="parcel-distribution-controls">
                          <div className="override-input-group">
                            <label>Artifact Directory Override (Optional)</label>
                            <input
                              className="form-control"
                              value={distributionDirs[ver.id] || ''}
                              onChange={event => setDistributionDirs(current => ({ ...current, [ver.id]: event.target.value }))}
                              placeholder={universalDistributionDir}
                            />
                          </div>
                          <div className="override-actions">
                            <button className="btn btn-distribute-selected" onClick={() => distributeSelected(ver)} disabled={actingKey !== null || !(selectedHosts[ver.id]?.length)}>
                              {actingKey === `distribute-selected-${ver.id}` ? <Loader2 size={14} className="spin" /> : <DownloadCloud size={14} />}
                              Distribute Selected
                            </button>
                            <button className="btn btn-distribute-all" onClick={() => distributeAll(ver)} disabled={actingKey !== null}>
                              {actingKey === `distribute-all-${ver.id}` ? <Loader2 size={14} className="spin" /> : <DownloadCloud size={14} />}
                              Distribute All
                            </button>
                          </div>
                        </div>
                      )}
                      {hosts.length === 0 ? (
                        <div className="parcel-empty-hosts">
                          <Server size={18} />
                          No hosts are registered yet.
                        </div>
                      ) : (
                        <div className="parcel-host-table">
                          <div className="parcel-host-row header">
                            <span className="col-host-select">
                              {canManage && (
                                <input
                                  type="checkbox"
                                  checked={hosts.length > 0 && (selectedHosts[ver.id]?.length || 0) === hosts.length}
                                  onChange={event => setSelectedHosts(current => ({
                                    ...current,
                                    [ver.id]: event.target.checked ? hosts.map(host => host.id) : [],
                                  }))}
                                />
                              )}
                              <span style={{ marginLeft: '8px' }}>Host</span>
                            </span>
                            <span>State</span>
                            <span>Destination Path</span>
                            <span>Action</span>
                          </div>
                          {hosts.map(host => {
                            const state = getHostParcel(ver.id, host.id);
                            const status = state?.status || 'AVAILABLE';
                            return (
                              <div key={host.id} className="parcel-host-row">
                                <div className="parcel-host">
                                  {canManage && (
                                    <input
                                      type="checkbox"
                                      checked={(selectedHosts[ver.id] || []).includes(host.id)}
                                      onChange={() => toggleHostSelection(ver.id, host.id)}
                                    />
                                  )}
                                  <div className="host-details">
                                    <strong>{host.hostname || host.id}</strong>
                                    <span className="host-uuid">{host.id}</span>
                                  </div>
                                </div>
                                <div>
                                  <span className={`parcel-status ${status.toLowerCase()}`}>
                                    {formatParcelStatus(status)}
                                  </span>
                                  {state?.errorMsg && <p className="parcel-error">{state.errorMsg}</p>}
                                </div>
                                <div className="parcel-host-destination">
                                  <input
                                    className="form-control"
                                    value={hostDistributionDirs[`${ver.id}:${host.id}`] || ''}
                                    onChange={event => setHostDistributionDirs(current => ({
                                      ...current,
                                      [`${ver.id}:${host.id}`]: event.target.value,
                                    }))}
                                    placeholder={distributionDirs[ver.id] || universalDistributionDir}
                                    disabled={!canManage}
                                  />
                                </div>
                                <div className="parcel-actions">
                                  {renderActions(ver, host, state)}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {canManage && showUploadModal && (
        <div className="modal-overlay" onClick={() => setShowUploadModal(false)}>
          <div className="modal upload-parcel-modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header upload-parcel-header">
              <div className="upload-parcel-heading">
                <h2>Upload Parcel Binary</h2>
                <p className="modal-subtitle">Upload a Kafka binary, Kafka Exporter binary, or JMX Exporter jar to the internal artifact repository.</p>
              </div>
              <button className="modal-close" onClick={() => setShowUploadModal(false)}>
                <X size={14} />
              </button>
            </div>

            <form onSubmit={handleUploadSubmit} style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
              <div className="modal-body">
                <div className="form-group">
                  <label>Service Type</label>
                  <select
                    className="form-control"
                    value={serviceType}
                    onChange={e => {
                      setServiceType(e.target.value);
                      setFile(null);
                      if (fileRef.current) fileRef.current.value = '';
                    }}
                  >
                    {artifactServiceOptions.map(option => (
                      <option key={option.value} value={option.value}>{option.label}</option>
                    ))}
                  </select>
                  <small className="form-hint">{selectedServiceOption.helper}</small>
                </div>

                <div className="form-group">
                  <label>Version Number</label>
                  <input
                    type="text"
                    className="form-control"
                    value={versionInput}
                    onChange={e => setVersionInput(e.target.value)}
                    placeholder={selectedServiceOption.versionPlaceholder}
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Repository Subdirectory (Optional)</label>
                  <input
                    type="text"
                    className="form-control"
                    value={uploadDirectory}
                    onChange={e => setUploadDirectory(e.target.value)}
                    placeholder={selectedServiceOption.directoryPlaceholder}
                  />
                </div>

                <div className="form-group">
                  <label>Binary File (.tgz or .jar)</label>
                  <div className="upload-dropzone" onClick={() => fileRef.current?.click()}>
                    <span className="upload-dropzone-icon-shell">
                      <Upload size={22} className="upload-dropzone-icon" />
                    </span>
                    {file ? (
                      <>
                        <span className="dropzone-filename">{file.name}</span>
                        <span className="dropzone-size">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                      </>
                    ) : (
                      <span className="dropzone-hint">Click to select a binary file</span>
                    )}
                    <input
                      type="file"
                      ref={fileRef}
                      style={{ display: 'none' }}
                      onChange={e => setFile(e.target.files?.[0] ?? null)}
                      accept={selectedServiceOption.fileAccept}
                    />
                  </div>
                  {!fileMatchesServiceType && (
                    <small className="form-error">Selected file does not match {selectedServiceOption.label}.</small>
                  )}
                </div>
              </div>

              <div className="modal-footer">
                <button type="button" className="btn btn-cancel-purple-outline" onClick={() => setShowUploadModal(false)}>
                  Cancel
                </button>
                <button type="submit" className="btn btn-primary-action" disabled={uploading || !file || !versionInput || !fileMatchesServiceType}>
                  {uploading ? 'Uploading...' : 'Upload'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {auditModalArtifact && (
        <div className="modal-overlay" onClick={() => setAuditModalArtifact(null)}>
          <div className="modal artifact-log-modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Artifacts Logs</h2>
              <button className="modal-close" onClick={() => setAuditModalArtifact(null)}>
                <X size={18} />
              </button>
            </div>

            <div className="modal-body" style={{ padding: '0 32px 24px 32px' }}>
              {artifactAuditLoading ? (
                <div className="artifact-log-empty"><Loader2 size={18} className="spin" /> Loading audit log...</div>
              ) : artifactAuditEvents.length === 0 ? (
                <div className="artifact-log-empty">No audit log entries found for this artifact.</div>
              ) : (
                <div className="artifact-log-box">
                  {artifactAuditEvents.map(event => {
                    const created = event.createdAt ? new Date(event.createdAt) : new Date();
                    const dateStr = created.toLocaleDateString('en-US') + ', ' + created.toLocaleTimeString('en-US');
                    const category = (event.category || 'PACKAGE').toUpperCase();
                    const action = (event.action || 'PACKAGE_UPLOADED').toUpperCase();
                    const status = (event.status || 'SUCCESS').toUpperCase();
                    const logLine = `${dateStr} ${category} ${action} ${status}`;
                    return (
                      <div key={event.id} className="log-line">
                        {logLine}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            <div className="modal-footer">
              <button type="button" className="btn btn-cancel-purple-outline" onClick={() => setAuditModalArtifact(null)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {deleteConfirmVer && (
        <div className="modal-overlay" onClick={() => setDeleteConfirmVer(null)}>
          <div className="modal delete-confirm-modal" onClick={e => e.stopPropagation()}>
            <div className="delete-modal-banner">
              <img src={orangeBanner} alt="Banner" className="delete-banner-image" />
              <button className="modal-close" onClick={() => setDeleteConfirmVer(null)}>
                <X size={14} />
              </button>
            </div>
            <div className="delete-confirm-content">
              <div className="delete-confirm-title-row">
                <AlertTriangle className="delete-alert-icon" size={20} />
                <h2>Delete Artifact</h2>
              </div>
              <p className="delete-confirm-subtitle">
                Are you sure you want to delete this artifact?
              </p>
              <p className="delete-confirm-desc">
                This action will permanently remove the artifact from the repository and cannot be undone.
              </p>
            </div>
            <div className="modal-footer delete-modal-footer">
              <button type="button" className="btn btn-cancel-pink-outline" onClick={() => setDeleteConfirmVer(null)}>
                Cancel
              </button>
              <button type="button" className="btn btn-primary-action" onClick={() => confirmDeleteArtifactBinary(deleteConfirmVer)}>
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function actionLabel(action: ParcelAction): string {
  return {
    distribute: 'Distribute',
    activate: 'Activate',
    deactivate: 'Deactivate',
    remove: 'Remove',
  }[action];
}

function actionIcon(action: ParcelAction) {
  return {
    distribute: DownloadCloud,
    activate: Power,
    deactivate: PowerOff,
    remove: Trash2,
  }[action];
}

import { useEffect, useMemo, useState } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate } from 'react-router-dom';
import {
  Activity, AlertTriangle, ExternalLink, Info, Network, Plus, RefreshCw, Server, X, FileCheck, FileText, FileCode,
  type LucideIcon
} from 'lucide-react';
import {
  Bar, BarChart, CartesianGrid, Cell, Legend, Pie, PieChart, Line, LineChart,
  ResponsiveContainer, Tooltip, XAxis, YAxis
} from 'recharts';
import { usePermissions } from '../hooks/usePermissions';
import { clusterStatusTone } from '../utils/clusterStatusTone';
import './Dashboard.css';

interface DashboardSummary {
  totalHosts: number;
  activeHosts: number;
  offlineHosts: number;
  pendingHosts: number;
  totalClusters: number;
  activeClusters: number;
  failedClusters: number;
  externalClusters: number;
  internalClusters: number;
  activeAlerts: number;
  runningTasks: number;
  failedTasks: number;
  activeParcels: number;
  failedParcels: number;
  runningServices: number;
  failedServices: number;
  firstClusterCreatedAt?: string;
  latestClusterCreatedAt?: string;
  lastActivityAt?: string;
}

interface ChartRow {
  name: string;
  status?: string;
  value?: number;
  usedGb?: number;
  freeGb?: number;
  totalGb?: number;
  usedPct?: number;
  success?: number;
  failed?: number;
  running?: number;
  label?: string;
}

interface ServiceRow {
  name: string;
  description: string;
  status: string;
  type: string;
}

interface ClusterHealthRow {
  id: string;
  name: string;
  mode?: string;
  kafkaVersion?: string;
  source?: string;
  status: string;
  reason: string;
  hostCount?: number;
  bootstrapServers?: string;
}

interface ActivityRow {
  id: string;
  level: string;
  message: string;
  clusterId?: string;
  createdAt?: string;
}

interface TaskRow {
  id: string;
  command: string;
  status: string;
  hostId: string;
  clusterName?: string;
  createdAt?: string;
  updatedAt?: string;
  errorMsg?: string;
}

interface DashboardPayload {
  generatedAt: string;
  summary: DashboardSummary;
  hostStatus: ChartRow[];
  clusterStatus: ChartRow[];
  clusterHealth: ClusterHealthRow[];
  hostDiskUsage: ChartRow[];
  taskStatus: ChartRow[];
  taskTimeline: ChartRow[];
  runningServices: ServiceRow[];
  failedServices: ServiceRow[];
  recentActivities: ActivityRow[];
  recentTasks: TaskRow[];
}

const emptyDashboard: DashboardPayload = {
  generatedAt: '',
  summary: {
    totalHosts: 0,
    activeHosts: 0,
    offlineHosts: 0,
    pendingHosts: 0,
    totalClusters: 0,
    activeClusters: 0,
    failedClusters: 0,
    externalClusters: 0,
    internalClusters: 0,
    activeAlerts: 0,
    runningTasks: 0,
    failedTasks: 0,
    activeParcels: 0,
    failedParcels: 0,
    runningServices: 0,
    failedServices: 0,
  },
  hostStatus: [],
  clusterStatus: [],
  clusterHealth: [],
  hostDiskUsage: [],
  taskStatus: [],
  taskTimeline: [],
  runningServices: [],
  failedServices: [],
  recentActivities: [],
  recentTasks: [],
};

const STATUS_COLORS: Record<string, string> = {
  SUCCESS: '#2AC792',
  ONLINE: '#2AC792',
  RUNNING: '#378ADD',
  IN_PROGRESS: '#378ADD',
  PENDING: '#BA7517',
  DELETING: '#BA7517',
  OFFLINE: '#E02424',
  FAILED: '#E02424',
  UNKNOWN: '#8b8982',
};

interface TaskLegendEntry { color?: string; value?: string }

const renderTaskLegend = ({ payload = [] }: { payload?: any }) => {
  return (
    <div className="task-legend">
      {payload.map((entry, index) => (
        <span key={`item-${index}`} className="task-legend-item">
          <i style={{ background: entry.color }} />
          {entry.value}
        </span>
      ))}
    </div>
  );
};

import { useAuth } from '../contexts/useAuth';
import { ClusterDeployment } from './ClusterDeployment';

export function Dashboard() {
  const navigate = useNavigate();
  const { decodedToken } = useAuth();
  const { canManage } = usePermissions();
  const [dashboard, setDashboard] = useState<DashboardPayload>(emptyDashboard);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showDeploymentModal, setShowDeploymentModal] = useState(false);
  const [deploymentStep, setDeploymentStep] = useState<'choice' | 'deploy'>('choice');
  const [serviceTab, setServiceTab] = useState<'running' | 'failed'>('running');
  const [taskTab, setTaskTab] = useState<'success' | 'failed'>('success');
  const [openInfo, setOpenInfo] = useState<'overview' | 'cluster-health' | null>(null);

  // Capitalize the first letter of username
  const username = useMemo(() => {
    const rawName = decodedToken?.preferred_username || decodedToken?.name || 'User';
    return rawName.charAt(0).toUpperCase() + rawName.slice(1);
  }, [decodedToken]);

  const fetchDashboard = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/api/v1/ui/dashboard');
      if (!res.ok) throw new Error(`Dashboard request failed (${res.status})`);
      setDashboard(await res.json());
    } catch (error: unknown) {
      setError(error instanceof Error ? error.message : 'Failed to load dashboard');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void fetchDashboard();
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  const summary = dashboard.summary;


  const kpis = useMemo(() => [
    {
      label: 'Active Hosts',
      value: `${summary.activeHosts.toString().padStart(2, '0')}`,
      detail: `${summary.offlineHosts} Offline | ${summary.pendingHosts} Pending`,
      icon: Server,
      tone: 'cyan',
    },
    {
      label: 'Clusters',
      value: `${summary.totalClusters.toString().padStart(2, '0')}`,
      detail: `${summary.internalClusters} Internal | ${summary.externalClusters} External`,
      icon: Network,
      tone: 'purple',
    },
    {
      label: 'External Clusters',
      value: `${summary.externalClusters.toString().padStart(2, '0')}`,
      detail: `${summary.externalClusters} External`,
      icon: ExternalLink,
      tone: 'indigo',
    },
    {
      label: 'Failed Service',
      value: `${summary.failedServices.toString().padStart(2, '0')}`,
      detail: `${summary.failedServices} Failed | ${summary.failedParcels} Issues`,
      icon: AlertTriangle,
      tone: 'pink',
    },
    {
      label: 'Running Service',
      value: `${summary.runningServices.toString().padStart(2, '0')}`,
      detail: `${summary.activeParcels} Active parcel`,
      icon: Activity,
      tone: 'green',
    },
  ], [summary]);

  const serviceIcon = () => {
    return FileCheck;
  };

  return (
    <div className="db animate-fade-in">
      <header className="db-hero">
        <div>
          <div>
            <h1>≡ƒæï Welcome {username}!</h1>
            <p className="db-subtitle-wrap">
              Dashboard overview
              <span className="db-info-wrap">
                <button
                  type="button"
                  className="db-info-button hero"
                  aria-label="About the dashboard overview"
                  aria-expanded={openInfo === 'overview'}
                  onClick={() => setOpenInfo(current => current === 'overview' ? null : 'overview')}
                >
                  <Info size={14} />
                </button>
                {openInfo === 'overview' && (
                  <span className="db-info-popover overview" role="status">
                    A summary of your Kafka environment, hosts, clusters, and service status.
                  </span>
                )}
              </span>
            </p>
          </div>
          <div className="db-hero-actions">
            <span className="db-generated">Last update: {relativeTime(dashboard.generatedAt)}</span>
            <button className="db-btn ghost" onClick={fetchDashboard} aria-label="Refresh dashboard" title="Refresh">
              <RefreshCw size={14} className={loading ? 'spin' : ''} />
            </button>
            {canManage && (
              <button className="db-btn primary" onClick={() => { setDeploymentStep('choice'); setShowDeploymentModal(true); }}>
                <Plus size={14} />
                New Cluster
              </button>
            )}
          </div>
        </div>

        <div className="db-kpi-grid">
          {kpis.map(kpi => (
            <article key={kpi.label} className={`db-kpi-card ${kpi.tone}`}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <div className="db-kpi-icon"><kpi.icon size={18} /></div>
                <span>{kpi.label}</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginTop: '12px' }}>
                <strong>{kpi.value}</strong>
                <small>{kpi.detail}</small>
              </div>
            </article>
          ))}
        </div>
      </header>

      {error && <div className="db-banner error">{error}</div>}

      <section className="db-cluster-health">
        <PanelTitle title="Cluster Health" detail={(
          <span className="db-info-wrap">
            <button
              type="button"
              className="db-info-button neutral"
              aria-label="About cluster health"
              aria-expanded={openInfo === 'cluster-health'}
              onClick={() => setOpenInfo(current => current === 'cluster-health' ? null : 'cluster-health')}
            >
              <Info size={16} />
            </button>
            {openInfo === 'cluster-health' && (
              <span className="db-info-popover cluster-health" role="status">
                Shows the current health and status of each configured Kafka cluster.
              </span>
            )}
          </span>
        )} />
        {dashboard.clusterHealth.length ? (
          <div className="db-cluster-list">
            {dashboard.clusterHealth.map(cluster => (
              <button
                key={cluster.id}
                className={`db-cluster-card ${healthTone(cluster.status)}`}
                onClick={() => navigate(`/clusters/${cluster.id}`)}
              >
                <span className="db-cluster-dot" />
                <div>
                  <strong>{cluster.name || 'Unnamed cluster'}</strong>
                  <small>{cluster.source || 'Cluster'} - Kafka {cluster.kafkaVersion || '-'} - {cluster.hostCount || 0} node{cluster.hostCount === 1 ? '' : 's'}</small>
                  <em>{cluster.reason}</em>
                </div>
                <b>{statusLabel(cluster.status)}</b>
              </button>
            ))}
          </div>
        ) : (
          <EmptyPanel text="No cluster records yet." compact />
        )}
      </section>

      <section className="db-main-grid">
        <article className="db-panel large">
          <PanelTitle title="Host Disk Usage" detail="From latest host heartbeat" />
          {summary.activeHosts === 0 ? (
            <EmptyPanel text="No hosts connected yet. Connect a host agent to view disk metrics." />
          ) : dashboard.hostDiskUsage.length ? (
            <ResponsiveContainer width="100%" height={270}>
              <BarChart data={dashboard.hostDiskUsage} layout="vertical" margin={{ top: 8, right: 22, bottom: 8, left: 18 }}>
                <CartesianGrid stroke="#eeeae3" horizontal={false} />
                <XAxis type="number" domain={[0, 100]} tickFormatter={v => `${v}%`} stroke="#8b8982" fontSize={11} />
                <YAxis dataKey="name" type="category" width={132} stroke="#5f5e5a" fontSize={11} tickLine={false} />
                <Tooltip content={<DiskTooltip />} />
                <Bar dataKey="usedPct" radius={[0, 6, 6, 0]} fill="#16ABC2" barSize={16} />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <EmptyPanel text="No disk data yet. Wait for host heartbeat metrics." />
          )}
        </article>

        <article className="db-panel">
          <PanelTitle title="Cluster Status" detail={`${summary.totalClusters} cluster records`} />
          <StatusDonut data={dashboard.clusterStatus} />
        </article>

        <article className="db-panel">
          <PanelTitle title="Host Fleet" detail={`${summary.activeHosts} active of ${summary.totalHosts}`} />
          <StatusDonut data={dashboard.hostStatus} />
        </article>
      </section>

      <section className="db-main-grid lower">
        <article className="db-panel large">
          <PanelTitle
            title="Task Activity"
            detail={
              <select className="db-panel-select">
                <option>Last 7 days</option>
              </select>
            }
          />
          <ResponsiveContainer width="100%" height={235}>
            <LineChart data={dashboard.taskTimeline} margin={{ top: 8, right: 18, bottom: 8, left: 0 }}>
              <CartesianGrid stroke="#eeeae3" vertical={false} />
              <XAxis dataKey="label" stroke="#8b8982" fontSize={11} tickLine={false} />
              <YAxis allowDecimals={false} stroke="#8b8982" fontSize={11} tickLine={false} />
              <Tooltip />
              <Legend content={renderTaskLegend} verticalAlign="bottom" align="left" wrapperStyle={{ bottom: -5 }} />
              <Line type="monotone" dataKey="failed" stroke="#DF678B" strokeWidth={2} dot={false} name="Failed" />
              <Line type="monotone" dataKey="running" stroke="#FFCF57" strokeWidth={2} dot={false} name="Running" />
              <Line type="monotone" dataKey="success" stroke="#098C60" strokeWidth={2} dot={false} name="Success" />
            </LineChart>
          </ResponsiveContainer>
        </article>

        <article className="db-panel services-panel">
          <PanelTitle title="Services" detail="" />
          <div className="tab-headers">
            <button type="button" className={serviceTab === 'running' ? 'active-tab' : ''} onClick={() => setServiceTab('running')}>Running ({summary.runningServices})</button>
            <button type="button" className={serviceTab === 'failed' ? 'active-tab' : ''} onClick={() => setServiceTab('failed')}>Failed ({summary.failedServices})</button>
          </div>
          <div className="tab-content">
            <ServiceList rows={serviceTab === 'running' ? dashboard.runningServices : dashboard.failedServices} iconFor={serviceIcon} />
          </div>
        </article>
      </section>

      <section className="db-bottom-grid">
        <article className="db-panel">
          <PanelTitle title="Activity Feed" detail="View all" onDetailClick={() => navigate('/audit')} />
          <div className="db-feed">
            {dashboard.recentActivities.length ? dashboard.recentActivities.map(item => (
              <div key={item.id} className="db-feed-row">
                <span className={`db-feed-level ${item.level?.toLowerCase() || 'info'}`}><FileText size={16} /></span>
                <div>
                  <strong>{item.message}</strong>
                  <small>{formatDateTime(item.createdAt)}</small>
                </div>
              </div>
            )) : <EmptyPanel text="No activity has been logged yet." compact />}
          </div>
        </article>

        <article className="db-panel">
          <PanelTitle title="Recent Tasks" detail="View all" onDetailClick={() => navigate('/jobs')} />
          <div className="tab-headers" role="tablist" aria-label="Recent task outcome">
            <button
              type="button"
              role="tab"
              aria-selected={taskTab === 'success'}
              className={taskTab === 'success' ? 'active-tab' : ''}
              onClick={() => setTaskTab('success')}
            >
              {statusLabel('SUCCESS')} ({dashboard.recentTasks.filter(isSuccessfulTask).length})
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={taskTab === 'failed'}
              className={taskTab === 'failed' ? 'active-tab' : ''}
              onClick={() => setTaskTab('failed')}
            >
              {statusLabel('FAILED')} ({dashboard.recentTasks.filter(t => !isSuccessfulTask(t)).length})
            </button>
          </div>
          <div className="db-task-list">
            {dashboard.recentTasks.filter(task => taskTab === 'success' ? isSuccessfulTask(task) : !isSuccessfulTask(task)).length
              ? dashboard.recentTasks.filter(task => taskTab === 'success' ? isSuccessfulTask(task) : !isSuccessfulTask(task)).map(task => (
                <div key={task.id} className="db-task-row">
                  <span className={`db-task-status ${task.status?.toLowerCase()}`}><FileCode size={16} /></span>
                  <div>
                    <strong>{prettyCommand(task.command)}</strong>
                    <small>{task.clusterName || task.hostId} - {formatDateTime(task.createdAt)}</small>
                    {task.errorMsg && <em>{task.errorMsg}</em>}
                  </div>
                </div>
              ))
              : <EmptyPanel text={taskTab === 'success' ? 'No successful tasks found.' : 'No failed tasks found.'} compact />}
          </div>
        </article>
      </section>

      {showDeploymentModal && createPortal(
        <div className="cd-modal-overlay" onClick={() => setShowDeploymentModal(false)}>
          {deploymentStep === 'choice' ? (
            <div className="cd-deployment-modal" onClick={e => e.stopPropagation()}>
              <div className="cd-deployment-modal-header">
                <div className="cd-deployment-modal-header-content">
                  <h2>Cluster Development</h2>
                  <p>Create a managed Kafka cluster or connect an exiting external cluster.</p>
                </div>
                <button className="cd-icon-btn close-btn" onClick={() => setShowDeploymentModal(false)} title="Close">
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"></path></svg>
                </button>
              </div>

              <div className="cd-deployment-cards-wrapper">
                <div className="cd-deployment-choice-grid">
                  <div className="cd-deployment-card">
                    <div className="cd-deployment-card-content">
                      <svg className="cluster-choice-icon managed" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                        <circle cx="12" cy="4.5" r="3.25" />
                        <path d="M12 7.75v6M5 13.75h14M5 13.75V17M19 13.75V17" fill="none" stroke="currentColor" strokeWidth="2.5" />
                        <rect x="2" y="17" width="6" height="5" rx="0.5" />
                        <rect x="16" y="17" width="6" height="5" rx="0.5" />
                      </svg>
                      <h3>Create your Cluster</h3>
                      <p>Build a new KRaft or ZooKeeper cluster on selected Tantor host</p>
                    </div>
                    <button className="cd-deployment-btn outline" onClick={(e) => { e.stopPropagation(); setShowDeploymentModal(false); navigate('/cluster-deployment'); }}>Create</button>
                  </div>

                  <div className="cd-deployment-card">
                    <div className="cd-deployment-card-content">
                      <svg className="cluster-choice-icon existing" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                        <path d="M22 11V3h-7v3H9V3H2v8h7V8h2v10h4v3h7v-8h-7v3h-2V8h2v3h7v-8zM7 9H4V5h3v4zm13-4h-3V5h3v4zm0 14h-3v-4h3v4z" />
                      </svg>
                      <h3>Existing Cluster</h3>
                      <p>Connect or discover an external Kafka cluster</p>
                    </div>
                    <button className="cd-deployment-btn outline" onClick={(e) => { e.stopPropagation(); setShowDeploymentModal(false); navigate('/external-clusters'); }}>Explorer</button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="cd-modal-container" onClick={e => e.stopPropagation()}>
              <button className="cd-modal-close" onClick={() => setShowDeploymentModal(false)}>
                <X size={20} />
              </button>
              <div className="cd-modal-content">
                <ClusterDeployment onClose={() => setShowDeploymentModal(false)} />
              </div>
            </div>
          )}
        </div>,
        document.body
      )}
    </div>
  );
}

function PanelTitle({ title, detail, onDetailClick }: { title: React.ReactNode; detail?: string | React.ReactNode; onDetailClick?: () => void }) {
  return (
    <div className="db-panel-title">
      <div>
        <h2>{title}</h2>
      </div>
      {onDetailClick ? (
        <button type="button" className="db-panel-detail" onClick={onDetailClick}>{detail}</button>
      ) : <span>{detail}</span>}
    </div>
  );
}

function EmptyPanel({ text, compact = false }: { text: string; compact?: boolean }) {
  return <div className={`db-empty-panel ${compact ? 'compact' : ''}`}>{text}</div>;
}

function StatusDonut({ data }: { data: ChartRow[] }) {
  const clean = data.filter(row => (row.value || 0) > 0);
  if (!clean.length) return <EmptyPanel text="No status data yet." compact />;

  return (
    <div className="db-donut-wrap">
      <div className="db-donut-legend">
        {clean.map(row => {
          const isGreen = row.status?.toUpperCase() === 'SUCCESS' || row.status?.toUpperCase() === 'ONLINE';
          const label = row.status?.toUpperCase() === 'SUCCESS' ? 'Success' : `${row.name} ${row.value}`;
          return (
            <span key={row.status || row.name} className={isGreen ? 'green-pill' : 'default-pill'}>
              <i style={{ background: STATUS_COLORS[row.status || 'UNKNOWN'] || STATUS_COLORS.UNKNOWN }} />
              {label}
            </span>
          );
        })}
      </div>
      <div style={{ display: 'flex', justifyContent: 'center', width: '100%', height: '180px' }}>
        <ResponsiveContainer width={180} height={180}>
          <PieChart width={180} height={180}>
            <Pie
              data={clean}
              dataKey="value"
              nameKey="name"
              innerRadius={80}
              outerRadius={90}
              paddingAngle={3}
            >
              {clean.map(row => <Cell key={row.status || row.name} fill={STATUS_COLORS[row.status || 'UNKNOWN'] || STATUS_COLORS.UNKNOWN} />)}
            </Pie>
            <Tooltip />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function ServiceList({ rows, iconFor }: { rows: ServiceRow[]; iconFor: (type: string) => LucideIcon }) {
  if (!rows.length) return <EmptyPanel text="No services found for this status." compact />;
  return (
    <div className="db-service-list">
      {rows.map(row => {
        const Icon = iconFor(row.type);
        return (
          <div key={`${row.name}-${row.status}`} className="db-service-row">
            <div className={`db-service-icon ${row.status.toLowerCase()}`}><Icon size={18} strokeWidth={2} /></div>
            <div>
              <strong>{row.name}</strong>
              <small>{row.description}</small>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function healthTone(status: string) {
  return clusterStatusTone(status) === 'state-positive' ? 'good' : 'bad';
}

function statusLabel(status: string) {
  if (!status) return 'Unknown';
  if (status.toUpperCase() === 'HEALTHY') return 'Healthy';
  return status.toLowerCase().replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

interface DiskTooltipRow { name: string; usedGb: number; totalGb: number; freeGb: number }

function DiskTooltip({ active, payload }: { active?: boolean; payload?: Array<{ payload: DiskTooltipRow }> }) {
  if (!active || !payload?.length) return null;
  const row = payload[0].payload;
  return (
    <div className="db-tooltip">
      <strong>{row.name}</strong>
      <span>{row.usedGb} GB used of {row.totalGb} GB</span>
      <span>{row.freeGb} GB free</span>
    </div>
  );
}

function relativeTime(value?: string) {
  if (!value) return '-';
  const time = new Date(value).getTime();
  if (Number.isNaN(time)) return '-';
  const diff = Date.now() - time;
  if (diff < 60_000) return 'just now';
  const minutes = Math.round(diff / 60_000);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function formatDateTime(value?: string) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleString([], {
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function prettyCommand(command?: string) {
  if (!command) return 'Task';
  return command.toLowerCase().split('_').map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
}

function isSuccessfulTask(task: TaskRow) {
  return ['SUCCESS', 'SUCCEEDED', 'COMPLETED', 'COMPLETED_SUCCESSFULLY'].includes(task.status?.toUpperCase() || '');
}

import { useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  AlertTriangle,
  ChevronLeft,
  CheckCircle2,
  Copy,
  RefreshCw,
  Server,
  Network,
  FileText,
  X,
  Wifi,
} from 'lucide-react';
import './ExternalClusters.css';

interface BootstrapResult {
  name?: string;
  success?: boolean;
  connected?: boolean;
  status?: string;
  bootstrapServers?: string;
  bootstrap_servers?: string;
  security_protocol?: string;
  mode?: string;
  kafkaMode?: string;
  clusterId?: string;
  cluster_id?: string;
  kafka_cluster_id?: string;
  brokerCount?: number;
  brokers?: unknown[];
  topicCount?: number;
  topic_count?: number;
  topics?: unknown[];
  controllerId?: string | number;
  controller_id?: string | number;
  kafka_version?: string;
  kafkaVersion?: string;
  hostname?: string;
  security?: string;
  environment?: string;
  socket_results?: unknown[];
  message?: string;
  discoveryKey?: string;
}

const registrationKafkaMode = (result: BootstrapResult | null): string => {
  const raw = String(result?.kafkaMode || result?.mode || '').trim();
  if (/^zookeeper$/i.test(raw) || /^zk$/i.test(raw)) return 'ZooKeeper';
  if (/^kraft$/i.test(raw)) return 'KRaft';
  return 'Unknown';
};

interface DiscoveryAgentStatus {
  id: string;
  agentName?: string;
  hostname?: string;
  ipAddresses?: string;
  status?: string;
  health?: 'green' | 'orange' | 'red' | string;
  stateLabel?: string;
  lastHeartbeat?: string;
  canExecuteTasks?: boolean;
  clusterId?: string | null;
}

const TRUSTSTORE_FILE_RULES: Record<string, { accept: string; extensions: string[]; label: string }> = {
  PKCS12: { accept: '.p12,.pfx', extensions: ['.p12', '.pfx'], label: 'PKCS12 truststore' },
  PEM: { accept: '.pem,.crt,.cer', extensions: ['.pem', '.crt', '.cer'], label: 'PEM certificate' },
};

export function ExternalClusters() {
  const navigate = useNavigate();
  const [banner, setBanner] = useState('');
  const [error, setError] = useState('');
  const [testing, setTesting] = useState(false);
  const [registering, setRegistering] = useState(false);
  const [openPanel, setOpenPanel] = useState<'bootstrap' | 'agent'>('bootstrap');
  const [agents, setAgents] = useState<DiscoveryAgentStatus[]>([]);
  const [agentsLoading, setAgentsLoading] = useState(false);
  const [clusterNameError, setClusterNameError] = useState('');
  const [checkingClusterName, setCheckingClusterName] = useState(false);
  const clusterNameValidationSequence = useRef(0);

  const [form, setForm] = useState({
    name: '',
    environment: 'prod',
    bootstrapServers: '',
    kafkaVersion: '',
    securityProtocol: 'PLAINTEXT',
    saslMechanism: 'PLAIN',
    saslUsername: '',
    saslPassword: '',
    truststoreType: 'PKCS12',
    truststorePassword: '',
    truststoreBase64: '',
    truststoreFilename: '',
    keystoreType: 'PKCS12',
    keystorePassword: '',
    keyPassword: '',
    keystoreBase64: '',
    keystoreFilename: '',
    disableHostnameVerification: false,
  });
  const [bootstrapResult, setBootstrapResult] = useState<BootstrapResult | null>(null);
  const [selectedAgents, setSelectedAgents] = useState<Record<string, string>>({});
  const bootstrapIsZooKeeper = registrationKafkaMode(bootstrapResult) === 'ZooKeeper';
  const truststoreFileRule = TRUSTSTORE_FILE_RULES[form.truststoreType] || TRUSTSTORE_FILE_RULES.PKCS12;

  const serverHint = useMemo(() => {
    const host = window.location.hostname || '<tantor-server-ip>';
    if (host === 'localhost' || host === '127.0.0.1') {
      return 'http://<tantor-server-ip-or-dns>:8443';
    }
    return `${window.location.protocol}//${host}:8443`;
  }, []);

  const agentConfig = useMemo(() => (
    `discovery:
  server_url: "${serverHint}"
  host_id: "discovery-<vm-hostname-or-ip>"
  agent_name: "tantor-discovery-<vm-hostname-or-ip>"
  scan_paths:
    - "/opt"
    - "/srv"
    - "/data"
    - "/usr/local"
    - "/var/lib"
  interval: "15s"
  task_poll_interval: "5s"
  node_name: ""
  restart_command: "systemctl restart kafka.service"
  systemd_use_sudo: false
  metrics_url: "http://localhost:7071/metrics"
  disable_metrics: false
  skip_precheck: false
  tls_insecure_skip_verify: true`
  ), [serverHint]);

  const loadAgents = useCallback(async () => {
    setAgentsLoading(true);
    try {
      const res = await fetch('/api/v1/ui/external-clusters/agents');
      if (res.ok) setAgents(await res.json());
    } catch (e: any) {
      console.error(e);
    } finally {
      setAgentsLoading(false);
    }
  }, []);

  useEffect(() => {
    void (async () => { await loadAgents(); })();
    const timer = window.setInterval(() => { void (async () => { await loadAgents(); })(); }, 10000);
    return () => window.clearInterval(timer);
  }, [loadAgents]);

  const formatHeartbeat = (value?: string) => {
    if (!value) return 'Never';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return 'Unknown';
    return date.toLocaleString([], {
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  const displayIp = (value?: string) => {
    if (!value) return '-';
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return parsed.join(', ') || '-';
    } catch {
      // fall through to raw value
    }
    return value;
  };

  const validateClusterName = async (value = form.name) => {
    const name = value.trim();
    const validationSequence = ++clusterNameValidationSequence.current;
    if (!name) {
      setClusterNameError('');
      setCheckingClusterName(false);
      return true;
    }

    setCheckingClusterName(true);
    try {
      const res = await fetch(`/api/v1/ui/external-clusters/name-availability?name=${encodeURIComponent(name)}`);
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || 'Unable to validate the cluster name.');
      if (validationSequence !== clusterNameValidationSequence.current) return false;
      const available = data.available === true;
      setClusterNameError(available ? '' : (data.message || 'A cluster with this name already exists. Choose a different name.'));
      return available;
    } catch (validationError) {
      if (validationSequence !== clusterNameValidationSequence.current) return false;
      setClusterNameError(validationError instanceof Error
        ? validationError.message
        : 'Unable to validate the cluster name.');
      return false;
    } finally {
      if (validationSequence === clusterNameValidationSequence.current) {
        setCheckingClusterName(false);
      }
    }
  };

  const testBootstrap = async () => {
    if (!form.bootstrapServers.trim()) return;
    setTesting(true);
    setError('');
    setBanner('');
    setBootstrapResult(null);
    try {
      const res = await fetch('/api/v1/ui/external-clusters/bootstrap/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      setBootstrapResult(data);

      if (data.brokers) {
        const initialSelection: Record<string, string> = {};
        data.brokers.forEach((b: unknown) => {
          if (b.hasActiveAgent && b.agentDiscoveryKey) {
            initialSelection[b.host] = b.agentDiscoveryKey;
          }
        });
        setSelectedAgents(initialSelection);
      }

      if (!res.ok || data.connected !== true) {
        throw new Error(data.message || 'Bootstrap connection failed');
      }
      setBanner('Kafka details fetched successfully.');
    } catch (e: unknown) {
      setError(e.message || 'Failed to inspect the Kafka cluster');
    } finally {
      setTesting(false);
    }
  };

  const handleFileUpload = (
    e: React.ChangeEvent<HTMLInputElement>,
    fieldBase64: string,
    fieldFilename: string,
    rule?: { extensions: string[]; label: string },
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (rule) {
      const fileName = file.name.toLowerCase();
      const isAllowed = rule.extensions.some(ext => fileName.endsWith(ext));
      if (!isAllowed) {
        e.target.value = '';
        setForm(prev => ({
          ...prev,
          [fieldBase64]: '',
          [fieldFilename]: ''
        }));
        setBootstrapResult(null);
        setBanner('');
        setError(`${rule.label} must use ${rule.extensions.join(' or ')} file format.`);
        return;
      }
    }
    setError('');
    const reader = new FileReader();
    reader.onload = (evt) => {
      const result = evt.target?.result;
      if (typeof result === 'string') {
        const base64Content = result.split(',')[1] || result;
        setForm(prev => ({
          ...prev,
          [fieldBase64]: base64Content,
          [fieldFilename]: file.name
        }));
      }
    };
    reader.readAsDataURL(file);
  };

  const registerBootstrap = async () => {
    if (!form.bootstrapServers.trim() || bootstrapResult?.connected !== true) return;
    if (!(await validateClusterName())) return;
    setRegistering(true);
    setError('');
    setBanner('');
    try {
      const kafkaMode = registrationKafkaMode(bootstrapResult);
      const normalizedBrokers = (bootstrapResult?.brokers || []).map((broker: unknown) =>
        kafkaMode === 'ZooKeeper'
          ? { ...broker, isBroker: true, isController: false }
          : broker
      );
      const payload = {
        ...form,
        clusterId: bootstrapResult?.cluster_id || bootstrapResult?.kafka_cluster_id || bootstrapResult?.clusterId,
        brokerCount: bootstrapResult?.brokerCount
          ?? bootstrapResult?.brokers?.filter((node: unknown) => node.isBroker !== false).length
          ?? 0,
        agentFound: !!bootstrapResult?.brokers?.some((b: unknown) => b.hasActiveAgent),
        security: form.securityProtocol,
        brokers: normalizedBrokers,
        controllerId: bootstrapResult?.controllerId || bootstrapResult?.controller_id || null,
        kafkaVersion: bootstrapResult?.kafkaVersion || bootstrapResult?.kafka_version || 'Unknown',
        kafkaMode,
        discoveryKey: bootstrapResult?.discoveryKey,
        selectedAgents: selectedAgents
      };

      const res = await fetch('/api/v1/ui/external-clusters/bootstrap/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        const message = data.message || data.error || 'Failed to register external cluster';
        if (res.status === 409) {
          setClusterNameError(message);
          return;
        }
        throw new Error(message);
      }
      setBanner(`External cluster ${data.name || form.name || 'connected'} connected.`);
      setClusterNameError('');
      setForm(prev => ({ ...prev, name: '', bootstrapServers: '', kafkaVersion: '' }));
      setBootstrapResult(null);
      navigate(`/clusters`);
    } catch (e: unknown) {
      setError(e.message || 'Failed to connect external cluster');
    } finally {
      setRegistering(false);
    }
  };

  const copyAgentConfig = async () => {
    await navigator.clipboard.writeText(agentConfig);
    setBanner('Discovery agent config copied.');
  };

  return (
    <div className="external-page animate-fade-in">
      <div className="external-wrapper">
        <header className="external-header">
          <div className="external-header-left">
            <div className="back-clickable-title" onClick={() => navigate('/clusters')}>
              <ChevronLeft size={24} className="back-arrow-icon" />
              <h1>External Kafka Clusters</h1>
            </div>
            <p>Connect an external Kafka cluster using its bootstrap URL.</p>
          </div>

          <div className="external-tab-switcher">
            <button
              className={`tab-btn ${openPanel === 'bootstrap' ? 'active' : ''}`}
              onClick={() => setOpenPanel('bootstrap')}
            >
              Connect external cluster
            </button>
            <button
              className={`tab-btn ${openPanel === 'agent' ? 'active' : ''}`}
              onClick={() => setOpenPanel('agent')}
            >
              Discovery Agent setup
            </button>
          </div>
        </header>

        {(banner || error) && (
          <div className={`external-banner ${error ? 'error' : 'success'}`}>
            {error ? <AlertTriangle size={16} /> : <CheckCircle2 size={16} />}
            <span>{error || banner}</span>
          </div>
        )}

        <section className="external-connect-grid">
          {openPanel === 'bootstrap' && (
            <div className="external-bootstrap-container">
              <div className="external-card bootstrap-server-card">
                <div className="card-header-title">
                  <h3>Bootstrap server</h3>
                </div>
                <div className="form-row-three">
                  <div className="form-field-group">
                    <label>Cluster Name (Optional)</label>
                    <input
                      type="text"
                      placeholder="prod-external-01"
                      value={form.name}
                      className={clusterNameError ? 'field-invalid' : ''}
                      aria-invalid={clusterNameError ? 'true' : 'false'}
                      aria-describedby="external-cluster-name-message"
                      onBlur={() => void validateClusterName()}
                      onChange={e => {
                        clusterNameValidationSequence.current += 1;
                        setCheckingClusterName(false);
                        setClusterNameError('');
                        setForm(prev => ({ ...prev, name: e.target.value }));
                      }}
                    />
                    {(checkingClusterName || clusterNameError) && (
                      <span
                        id="external-cluster-name-message"
                        className={clusterNameError ? 'field-error-message' : 'field-validation-message'}
                      >
                        {clusterNameError || 'Checking name availability...'}
                      </span>
                    )}
                  </div>
                  <div className="form-field-group">
                    <label>Environment</label>
                    <select
                      value={form.environment}
                      onChange={e => setForm(prev => ({ ...prev, environment: e.target.value }))}
                    >
                      <option value="dev">Development</option>
                      <option value="test">Test</option>
                      <option value="staging">Staging</option>
                      <option value="prod">Production</option>
                    </select>
                  </div>
                  <div className="form-field-group bootstrap-url-field">
                    <label>Bootstrap URL</label>
                    <input
                      type="text"
                      placeholder="Broker host and port"
                      value={form.bootstrapServers}
                      onChange={e => {
                        setForm(prev => ({ ...prev, bootstrapServers: e.target.value }));
                        setBootstrapResult(null);
                      }}
                      onKeyDown={e => {
                        if (e.key === 'Enter') testBootstrap();
                      }}
                    />
                  </div>
                </div>
              </div>

              <div className="external-card security-config-card">
                <div className="card-header-title">
                  <h3>Security Configuration</h3>
                </div>
                <div className="form-grid-columns">
                  <div className="form-field-group security-protocol-field">
                    <label>Security Protocol</label>
                    <select
                      value={form.securityProtocol}
                      onChange={e => {
                        setForm(prev => ({ ...prev, securityProtocol: e.target.value }));
                        setBootstrapResult(null);
                      }}
                    >
                      <option value="PLAINTEXT">PLAINTEXT</option>
                      <option value="SSL">SSL</option>
                      <option value="SASL_PLAINTEXT">SASL_PLAINTEXT</option>
                      <option value="SASL_SSL">SASL_SSL</option>
                    </select>
                  </div>

                  {(form.securityProtocol === 'SASL_PLAINTEXT' || form.securityProtocol === 'SASL_SSL') && (
                    <>
                      <div className="form-field-group">
                        <label>SASL Mechanism</label>
                        <select
                          value={form.saslMechanism}
                          onChange={e => {
                            setForm(prev => ({ ...prev, saslMechanism: e.target.value }));
                            setBootstrapResult(null);
                          }}
                        >
                          <option value="PLAIN">PLAIN</option>
                          <option value="SCRAM-SHA-256">SCRAM-SHA-256</option>
                          <option value="SCRAM-SHA-512">SCRAM-SHA-512</option>
                        </select>
                      </div>
                      <div className="form-field-group">
                        <label>SASL Username</label>
                        <input
                          type="text"
                          placeholder="Username"
                          value={form.saslUsername}
                          onChange={e => {
                            setForm(prev => ({ ...prev, saslUsername: e.target.value }));
                            setBootstrapResult(null);
                          }}
                        />
                      </div>
                      <div className="form-field-group">
                        <label>SASL Password</label>
                        <input
                          type="password"
                          placeholder="Password"
                          value={form.saslPassword}
                          onChange={e => {
                            setForm(prev => ({ ...prev, saslPassword: e.target.value }));
                            setBootstrapResult(null);
                          }}
                        />
                      </div>
                    </>
                  )}

                  {(form.securityProtocol === 'SSL' || form.securityProtocol === 'SASL_SSL') && (
                    <>
                      <div className="form-field-group">
                        <label>Truststore Type</label>
                        <select
                          value={form.truststoreType}
                          onChange={e => {
                            setForm(prev => ({
                              ...prev,
                              truststoreType: e.target.value,
                              truststoreBase64: '',
                              truststoreFilename: '',
                            }));
                            setBootstrapResult(null);
                          }}
                        >
                          <option value="PKCS12">PKCS12</option>
                          <option value="PEM">PEM / X.509</option>
                        </select>
                      </div>
                      <div className="form-field-group">
                        <label>Truststore File (CA Certificate)</label>
                        <div className="file-upload-custom-wrapper">
                          <label className="file-upload-custom-btn">
                            <FileText size={15} />
                            <span>Choose file</span>
                            <input
                              key={form.truststoreType}
                              type="file"
                              accept={truststoreFileRule.accept}
                              onChange={e => {
                                handleFileUpload(e, 'truststoreBase64', 'truststoreFilename', truststoreFileRule);
                                setBootstrapResult(null);
                              }}
                              style={{ display: 'none' }}
                            />
                          </label>
                          {form.truststoreFilename && (
                            <div className="file-attached-badge">
                              <span className="file-attached-label">{form.truststoreFilename} attached</span>
                              <button
                                type="button"
                                className="clear-file-btn"
                                onClick={() => {
                                  setForm(prev => ({
                                    ...prev,
                                    truststoreBase64: '',
                                    truststoreFilename: '',
                                  }));
                                  setBootstrapResult(null);
                                }}
                                aria-label="Remove file"
                              >
                                <X size={12} />
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="form-field-group ssl-hostname-field">
                        <label>Disable Hostname Verification</label>
                        <div className="checkbox-wrapper">
                          <input
                            type="checkbox"
                            checked={form.disableHostnameVerification}
                            onChange={e => {
                              setForm(prev => ({ ...prev, disableHostnameVerification: e.target.checked }));
                              setBootstrapResult(null);
                            }}
                          />
                          <span>Skip checking hostname in certificate</span>
                        </div>
                      </div>
                      {form.truststoreType !== 'PEM' && (
                        <div className="form-field-group ssl-password-field">
                          <label>Truststore Password</label>
                          <input
                            type="password"
                            placeholder="Password"
                            value={form.truststorePassword}
                            onChange={e => {
                              setForm(prev => ({ ...prev, truststorePassword: e.target.value }));
                              setBootstrapResult(null);
                            }}
                          />
                        </div>
                      )}
                    </>
                  )}
                </div>
              </div>

              {testing && (
                <div className="inspection-loading">
                  <RefreshCw size={15} className="spin" />
                  Testing direct connection via Kafka Admin API...
                </div>
              )}

              {bootstrapResult && (
                <div className={`inspection-result ${(bootstrapResult.success ?? bootstrapResult.connected) ? 'ok' : 'error'}`}>
                  <div className="inspection-result-header">
                    <div className="status-icon-wrapper">
                      {(bootstrapResult.success ?? bootstrapResult.connected) ? (
                        <span className="success-check-dot">Γ£ö</span>
                      ) : (
                        <span className="error-warn-dot">ΓÜá</span>
                      )}
                    </div>
                    <div className="status-info-col">
                      <strong className="status-title">{form.name || bootstrapResult.name || 'External Kafka Cluster'}</strong>
                      <span className="status-desc">{(bootstrapResult.success ?? bootstrapResult.connected) ? 'Bootstrap connection verified' : 'Bootstrap connection failed'}</span>
                    </div>
                  </div>

                  <div className="bootstrap-summary">
                    <div className="summary-item">
                      <span>{bootstrapResult.brokerCount
                        ?? bootstrapResult.brokers?.filter((node: unknown) => node.isBroker !== false).length
                        ?? 0} broker(s) detected</span>
                    </div>
                    <div className="summary-item">
                      <span>
                        Version: {(() => {
                          const v = bootstrapResult.kafkaVersion || bootstrapResult.kafka_version || 'Auto-detected';
                          return v === 'auto-detected by Kafka client' ? 'Auto-detected' : v;
                        })()}
                      </span>
                    </div>
                    <div className="summary-item">
                      <span>
                        Mode: {(() => {
                          const m = bootstrapResult.mode || bootstrapResult.kafkaMode || 'Auto-detected';
                          return m === 'auto-detected by Kafka client' ? 'Auto-detected' : m;
                        })()}
                      </span>
                    </div>
                    <div className="summary-item">
                      <span>
                        Security: {form.securityProtocol || bootstrapResult.security_protocol || 'PLAINTEXT'}
                      </span>
                    </div>
                  </div>

                  {bootstrapResult.brokers && bootstrapResult.brokers.length > 0 && (
                    <div className="inspection-brokers" style={{ marginTop: '16px', background: '#f8fafc', padding: '12px', borderRadius: '6px', border: '1px solid #e2e8f0' }}>
                      <h4 style={{ marginBottom: '8px', fontSize: '12px', fontWeight: '600', color: '#64748b', textTransform: 'uppercase' }}>Discovered Nodes</h4>
                      <table style={{ width: '100%', fontSize: '13px', borderCollapse: 'collapse' }}>
                        <thead>
                          <tr style={{ borderBottom: '1px solid #cbd5e1', textAlign: 'left', color: '#64748b' }}>
                            <th style={{ padding: '6px', width: '40px' }}></th>
                            <th style={{ padding: '6px' }}>Node ID</th>
                            <th style={{ padding: '6px' }}>Host</th>
                            <th style={{ padding: '6px' }}>Port</th>
                            <th style={{ padding: '6px' }}>Role</th>
                          </tr>
                        </thead>
                        <tbody>
                          {bootstrapResult.brokers.map((broker: unknown) => {
                            const isSelected = !!selectedAgents[(broker as any).host];
                            const hasAgent = !!(broker as any).hasActiveAgent;
                            return (
                              <tr key={(broker as any).node_id || (broker as any).broker_id || (broker as any).id} style={{ borderBottom: '1px solid #e2e8f0', background: isSelected ? '#f0fdf4' : 'transparent' }}>
                                <td style={{ padding: '6px', textAlign: 'center' }}>
                                  <input
                                    type="checkbox"
                                    checked={isSelected}
                                    disabled={false}
                                    onChange={(e) => {
                                      setSelectedAgents(prev => {
                                        const next = { ...prev };
                                        if (e.target.checked) {
                                          next[(broker as any).host] = (broker as any).agentDiscoveryKey || (broker as any).host;
                                        } else {
                                          delete next[(broker as any).host];
                                        }
                                        return next;
                                      });
                                    }}
                                    style={{ cursor: 'pointer' }}
                                  />
                                </td>
                                <td style={{ padding: '6px' }}><strong>{(broker as any).node_id || (broker as any).broker_id || (broker as any).id}</strong></td>
                                <td style={{ padding: '6px' }}>
                                  {(broker as any).host}
                                  {!hasAgent && <span style={{ display: 'block', fontSize: '11px', color: '#94a3b8' }}>No telemetry / unmanaged</span>}
                                </td>
                                <td style={{ padding: '6px' }}>{(broker as any).port}</td>
                                <td style={{ padding: '6px' }}>
                                  {bootstrapIsZooKeeper ? (
                                    <span style={{ color: '#3b82f6', fontWeight: 500 }}>Broker</span>
                                  ) : (broker as any).isController && (broker as any).isBroker ? (
                                    <span style={{ color: '#059669', fontWeight: 500 }}>Controller + Broker</span>
                                  ) : (broker as any).isController ? (
                                    <span style={{ color: '#7c3aed', fontWeight: 500 }}>Controller</span>
                                  ) : (
                                    <span style={{ color: '#3b82f6', fontWeight: 500 }}>Broker</span>
                                  )}
                                </td>
                              </tr>
                            )
                          })}
                        </tbody>
                      </table>
                    </div>
                  )}

                  {bootstrapResult.message && !(bootstrapResult.success ?? bootstrapResult.connected) && (
                    <p className="inspection-error-message">{bootstrapResult.message}</p>
                  )}
                </div>
              )}

              <div className="external-actions-row">
                <button className="action-btn cancel-btn" onClick={() => navigate('/clusters')}>
                  Cancel
                </button>
                <button
                  className="action-btn test-btn"
                  onClick={testBootstrap}
                  title="Test Connection"
                  disabled={!form.bootstrapServers.trim() || testing}
                >
                  <RefreshCw size={14} className={testing ? 'spin' : ''} />
                  Test Connection
                </button>
                <button
                  className={`action-btn connect-btn ${bootstrapResult?.connected === true ? 'active' : ''}`}
                  onClick={registerBootstrap}
                  disabled={registering || checkingClusterName || !!clusterNameError || bootstrapResult?.connected !== true}
                >
                  {registering ? <RefreshCw size={14} className="spin" /> : <Network size={14} />}
                  Connect Cluster
                </button>
              </div>
            </div>
          )}

          {openPanel === 'agent' && (
            <div className="external-card agent-card">
              <div className="card-header-title">
                <h3>Discovery Agent</h3>
                <p className="card-header-subtitle">Full management path for restart, host metrics, and config persistence.</p>
              </div>
              <hr className="agent-divider" />

              <div className="agent-connectivity-header">
                <div>
                  <h3>Agent connectivity</h3>
                  <p>Shows discovery agents that are polling this Tantor server, even before Kafka is detected.</p>
                </div>
                <button className="btn" onClick={loadAgents} disabled={agentsLoading} aria-label="Refresh agents" title="Refresh">
                  <RefreshCw size={14} className={agentsLoading ? 'spin' : ''} />
                </button>
              </div>

              {agents.length === 0 ? (
                <div className="agent-empty-state">
                  <Wifi size={18} />
                  <div>
                    <strong>No discovery agent polling yet</strong>
                    <span>Start the agent on a client VM and this area will show the connection heartbeat.</span>
                  </div>
                </div>
              ) : (
                <div className="agent-status-grid">
                  {agents.map(agent => (
                    <div className={`agent-status-card ${agent.health || 'orange'}`} key={agent.id}>
                      <div className="agent-status-top">
                        <span className="agent-status-dot" />
                        <strong>{agent.agentName || agent.id}</strong>
                      </div>
                      <div className="agent-status-meta">
                        <span>{agent.stateLabel || agent.status || 'Unknown'}</span>
                        <span>Host: {agent.hostname || '-'}</span>
                        <span>IP: {displayIp(agent.ipAddresses)}</span>
                        <span>Last poll: {formatHeartbeat(agent.lastHeartbeat)}</span>
                        <span>{agent.canExecuteTasks ? 'Task control enabled' : 'Read-only heartbeat'}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              <hr className="agent-divider" />

              <div className="agent-flow">
                <div className="flow-step">
                  <span className="step-number">1</span>
                  <span className="step-text">Build or copy tantor-discovery-agent-linux to the Kafka VM.</span>
                </div>
                <div className="flow-step">
                  <span className="step-number">2</span>
                  <span className="step-text">Set server_url to this Tantor backend.</span>
                </div>
                <div className="flow-step">
                  <span className="step-number">3</span>
                  <span className="step-text">Run it with nohup; discovered clusters will report metrics and handle restart tasks.</span>
                </div>
              </div>

              <div className="code-block-container">
                <div className="code-block-header">
                  <button className="copy-btn" onClick={copyAgentConfig} title="Copy config">
                    <Copy size={16} />
                  </button>
                </div>
                <div className="code-block-body">
                  <pre>{agentConfig}</pre>
                </div>
              </div>

              <div className="agent-note">
                <Server size={18} className="note-icon" />
                <span className="note-text">The agent auto-detects KRaft vs ZooKeeper from Kafka properties. Users do not select the mode manually.</span>
              </div>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Plus, RefreshCw, Trash2, X } from 'lucide-react';
import { usePermissions } from '../hooks/usePermissions';
import { confirmAction, notifyAction } from '../components/confirmUtils';
import './Hosts.css';

interface HostInfo {
  id: string;
  hostname: string;
  status: string;
  agentStatus?: string;
  ipAddresses?: string;
  [key: string]: unknown;
}

export function Hosts() {
  const { canManage } = usePermissions();
  const [hosts, setHosts] = useState<HostInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [hasLoaded, setHasLoaded] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [selectedPendingIds, setSelectedPendingIds] = useState<Record<string, boolean>>({});
  const [connectingAgents, setConnectingAgents] = useState(false);

  const fetchHosts = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/v1/ui/hosts');
      if (res.ok) setHosts(await res.json());
    } catch (e) {
      console.error(e);
    }
    setLoading(false);
    setHasLoaded(true);
  }, []);

  const deleteHost = async (id: string) => {
    if (!canManage) return;
    if (!(await confirmAction('Disconnect this node? It will move back to discovered nodes and can be connected again.'))) return;
    try {
      const res = await fetch(`/api/v1/ui/hosts/${id}`, { method: 'DELETE' });
      if (res.ok) {
        fetchHosts();
      } else {
        const errorData = await res.json().catch(() => ({}));
        notifyAction(errorData.message || 'Failed to disconnect node.');
      }
    } catch (e) {
      console.error(e);
      notifyAction('An error occurred while disconnecting the node.');
    }
  };

  useEffect(() => {
    void (async () => { await fetchHosts(); })();
    const t = setInterval(() => { void (async () => { await fetchHosts(); })(); }, 5000);
    return () => clearInterval(t);
  }, [fetchHosts]);

  const parseIpList = (raw: unknown): string[] => {
    if (Array.isArray(raw)) return raw.map(String).map(ip => ip.trim()).filter(Boolean);
    if (typeof raw === 'string' && raw.startsWith('[')) {
      try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed.map(String).map(ip => ip.trim()).filter(Boolean);
      } catch { /* ignore */ }
    }
    if (typeof raw === 'string') return raw.split(',').map(ip => ip.trim()).filter(Boolean);
    return [];
  };

  const displayIp = (raw: unknown) => {
    const ips = parseIpList(raw);
    return ips.find(ip => ip.startsWith('192.168.'))
      || ips.find(ip => !ip.startsWith('127.') && !ip.startsWith('172.'))
      || ips[0]
      || 'Unknown';
  };

  const activeHosts = hosts.filter(h => h.status !== 'PENDING' && h.status !== 'REMOVED');
  const activeHostIps = new Set(activeHosts.map(host => displayIp(host.ipAddresses)));
  const pendingHosts = Array.from(
    hosts
      .filter(h => h.status === 'PENDING' && !activeHostIps.has(displayIp(h.ipAddresses)))
      .reduce<Map<string, HostInfo>>((byIp, host) => {
        const ip = displayIp(host.ipAddresses);
        const existing = byIp.get(ip);
        const heartbeat = Date.parse(host.lastHeartbeat || '') || 0;
        const existingHeartbeat = Date.parse(existing?.lastHeartbeat || '') || 0;
        const expectedSuffix = `-${ip.split('.').pop()}`;
        const isCanonicalId = String(host.id || '').endsWith(expectedSuffix);
        const existingIsCanonicalId = String(existing?.id || '').endsWith(expectedSuffix);

        if (
          !existing
          || (isCanonicalId && !existingIsCanonicalId)
          || (isCanonicalId === existingIsCanonicalId && heartbeat > existingHeartbeat)
        ) {
          byIp.set(ip, host);
        }
        return byIp;
      }, new Map<string, HostInfo>())
      .values(),
  );
  const selectedCount = pendingHosts.filter(host => selectedPendingIds[host.id]).length;
  const allPendingSelected = pendingHosts.length > 0 && selectedCount === pendingHosts.length;

  const togglePendingHost = (id: string) => {
    if (!canManage) return;
    setSelectedPendingIds(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const toggleAllPendingHosts = () => {
    if (!canManage) return;
    if (allPendingSelected) {
      setSelectedPendingIds({});
      return;
    }
    setSelectedPendingIds(Object.fromEntries(pendingHosts.map(host => [host.id, true])));
  };

  const connectSelectedAgents = async () => {
    if (!canManage) return;
    const selectedIds = pendingHosts.filter(host => selectedPendingIds[host.id]).map(host => host.id);
    if (selectedIds.length === 0) return;
    setConnectingAgents(true);
    try {
      const results = await Promise.allSettled(
        selectedIds.map(id => fetch(`/api/v1/ui/hosts/${id}/approve`, { method: 'POST' }))
      );
      const failed = results.filter(result => result.status === 'rejected'
        || (result.status === 'fulfilled' && !result.value.ok)).length;
      if (failed > 0) {
        notifyAction(`${failed} agent${failed === 1 ? '' : 's'} could not be connected. Refreshing the list now.`);
      }
      setSelectedPendingIds({});
      await fetchHosts();
    } finally {
      setConnectingAgents(false);
    }
  };

  return (
    <div className="hosts-page animate-fade-in">
      <header className="page-header flex-between">
        <div>
          <h1>Hosts</h1>
          <p>Manage and monitor physical and virtual nodes</p>
        </div>
        <div className="header-actions">
          <button className="btn icon-only round" onClick={fetchHosts} title="Refresh" aria-label="Refresh hosts">
            <RefreshCw size={16} className={loading ? 'spin' : ''} />
          </button>
          {canManage && (
            <button className="btn btn-primary-action agent-connectivity-btn" onClick={() => setShowEnrollModal(true)}>
              <Plus size={20} strokeWidth={2} aria-hidden="true" />
              <span>Agent Connectivity</span>
            </button>
          )}
        </div>
      </header>

      {activeHosts.length === 0 && hasLoaded ? (
        <div className="hosts-empty-state">
          <div className="empty-illustration">
            <svg width="102" height="74" viewBox="0 0 102 74" fill="none" xmlns="http://www.w3.org/2000/svg">
              <rect x="0.5" y="0.5" width="101" height="21" rx="2.5" fill="white" stroke="#E5E7EB"/>
              <rect x="10" y="8" width="14" height="2" rx="1" fill="#8B5CF6"/>
              <rect x="10" y="13" width="28" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="60" y="8" width="14" height="2" rx="1" fill="#8B5CF6"/>
              <rect x="60" y="13" width="28" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="0.5" y="26.5" width="101" height="21" rx="2.5" fill="white" stroke="#E5E7EB"/>
              <rect x="10" y="34" width="14" height="2" rx="1" fill="#8B5CF6"/>
              <rect x="10" y="39" width="28" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="60" y="34" width="14" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="60" y="39" width="28" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="0.5" y="52.5" width="101" height="21" rx="2.5" fill="white" stroke="#E5E7EB"/>
              <rect x="10" y="60" width="14" height="2" rx="1" fill="#8B5CF6"/>
              <rect x="10" y="65" width="28" height="2" rx="1" fill="#D1D5DB"/>
              <rect x="60" y="60" width="14" height="2" rx="1" fill="#8B5CF6"/>
              <rect x="60" y="65" width="28" height="2" rx="1" fill="#D1D5DB"/>
            </svg>
          </div>
          <h3>No Host at this movment</h3>
          <p>Create your first rule to start identifying duplicate records and improving your data quality.</p>
        </div>
      ) : (
      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th style={{ width: '100px' }}>Status</th>
              <th style={{ width: '110px' }}>Availability</th>
              <th style={{ width: '160px' }}>Agent name</th>
              <th style={{ width: '160px' }}>Host name</th>
              <th style={{ width: '120px' }}>IP address</th>
              <th style={{ width: '160px' }}>Agent</th>
              <th style={{ width: '140px' }}>CPU</th>
              <th style={{ width: '140px' }}>Memory</th>
            </tr>
          </thead>
          <tbody>
            {!hasLoaded && activeHosts.length === 0 ? (
              <tr>
                <td colSpan={8}>
                  <div className="empty-state">
                    Loading connected agents...
                  </div>
                </td>
              </tr>
            ) : activeHosts.map(host => {
              const ip = displayIp(host.ipAddresses);
              const cpu = host.cpuUsagePct ? Math.round(host.cpuUsagePct) : 0;
              const mem = (host as any).memTotalMb > 0
                ? Math.round(((host as any).memUsedMb / (host as any).memTotalMb) * 100)
                : 0;
              return (
                <tr key={host.id}>
                  <td>
                    <span className={`host-status-badge ${(host.agentStatus ?? 'offline').toLowerCase()}`}>
                      {(host.agentStatus ?? 'OFFLINE').toUpperCase() === 'ONLINE' && (
                        <span className="status-dot"></span>
                      )}
                      <span>
                        {host.agentStatus ? host.agentStatus.charAt(0) + host.agentStatus.slice(1).toLowerCase() : 'Offline'}
                      </span>
                    </span>
                  </td>
                  <td>
                    <div className="availability-cell">
                      <span className={`availability-badge ${
                        host.status === 'OFFLINE' ? 'unavailable' :
                        host.status === 'CRITICAL' ? 'critical' :
                        ['OCCUPIED_INTERNAL', 'OCCUPIED_EXTERNAL'].includes(host.status || '') ? 'occupied' : 'available'
                      }`}>
                        {host.status === 'OCCUPIED_INTERNAL' ? 'Occupied' :
                         host.status === 'OCCUPIED_EXTERNAL' ? 'Occupied' :
                         host.status === 'OFFLINE' ? 'Unavailable' :
                         host.status === 'REMOVED' ? 'Removed' :
                         host.status === 'CRITICAL' ? 'Critical' : 'Available'}
                      </span>
                    </div>
                  </td>
                  <td>{host.agentName ?? '-'}</td>
                  <td>{host.hostname}</td>
                  <td>{ip}</td>
                  <td>
                    <div className="agent-kind-cell">
                      <span>V{host.agentVersion || 'N/A'}</span>
                      <small>{host.agentPath || 'Path unavailable'}</small>
                    </div>
                  </td>
                  <td>
                    <div className="metric-bar-stacked">
                      <span>{cpu}%</span>
                      <div className="bar-track">
                        <div className="bar-fill normal" style={{ width: `${cpu}%` }} />
                      </div>
                    </div>
                  </td>
                  <td>
                    <div className="metric-bar-stacked">
                      <span>{mem}%</span>
                      <div className="bar-track">
                        <div className="bar-fill normal" style={{ width: `${mem}%` }} />
                      </div>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      )}

      {canManage && showEnrollModal && (
        <div className="modal-overlay" onClick={() => setShowEnrollModal(false)}>
          <div className="modal agent-connectivity-modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Agent Connectivity</h2>
              <button className="modal-close" onClick={() => setShowEnrollModal(false)}>
                <X size={14} />
              </button>
            </div>

            <div className="modal-body-content">
              {pendingHosts.length === 0 ? (
                <>
                  <div className="empty-pending" style={{ marginTop: '20px' }}>
                    <h3>No new nodes discovered</h3>
                    <p>Run the agent script on a VM to discover it.</p>
                  </div>
                </>
              ) : (
                <div className="discovered-nodes-wrapper">
                  <div className="modal-section-header">
                    <p className="modal-section-title">Discovered Nodes</p>
                    <label className="pending-select-all">
                      <input type="checkbox" checked={allPendingSelected} onChange={toggleAllPendingHosts} />
                      <span>Select all</span>
                    </label>
                  </div>
                  <div className="discovered-nodes-list">
                    {pendingHosts.map(host => (
                      <div key={host.id} className={`pending-node selectable ${selectedPendingIds[host.id] ? 'selected' : ''}`} onClick={() => togglePendingHost(host.id)}>
                        <label className="pending-node-select" onClick={event => event.stopPropagation()}>
                          <input
                            type="checkbox"
                            checked={!!selectedPendingIds[host.id]}
                            onChange={() => togglePendingHost(host.id)}
                          />
                        </label>
                        <div className="pending-node-info">
                          <p className="name">{host.agentName || host.hostname}</p>
                          <p className="ip">{displayIp(host.ipAddresses)} - {host.agentPath || 'Path unavailable'}</p>
                        </div>
                        <div className="pending-node-actions">
                          <button className="btn icon-only danger" title="Reject & remove" onClick={(event) => { event.stopPropagation(); deleteHost(host.id); }}>
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="modal-footer right">
              <button className="btn btn-outline" onClick={() => setShowEnrollModal(false)}>Cancel</button>
              {pendingHosts.length > 0 && (
                <button className="btn btn-primary-action" disabled={selectedCount === 0 || connectingAgents} onClick={connectSelectedAgents}>
                  {connectingAgents ? 'Connecting...' : 'Connect'}
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { Download, RefreshCw, Loader2, Save, UploadCloud, X, Plus, Trash2, Server, GitCompare, FileCheck } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { useState, useCallback, useEffect, useMemo } from 'react';
import { usePermissions } from '../hooks/usePermissions';
import './ConfigEditor.css';
import './ConfigVersioning.css';

interface StaticConfigFile {
  id: string;
  serviceId?: string;
  hostId?: string;
  nodeId?: number;
  label: string;
  description?: string;
  path: string;
  role?: string;
  properties: Record<string, unknown>;
}

interface ServiceTopologyItem {
  hostId: string;
  hostAddress: string;
  role: string;
  nodeId: number;
  systemdUnit: string;
  configPath: string;
}

interface ConfigPayload {
  serviceTopology?: ServiceTopologyItem[];
  staticConfigs: { configFiles?: StaticConfigFile[] };
}

interface ConfigDiff {
  key: string;
  type: 'ADDED' | 'REMOVED' | 'MODIFIED';
  oldValue: string;
  newValue: string;
}

interface PreviewResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  diff: ConfigDiff[];
}

interface ConfigVersion {
  id: string;
  configVersion: number;
  component: string;
  configFileName: string;
  status: string;
  approvalRequired: boolean;
  createdBy: string;
  approvedBy?: string;
  createdAt: string;
  appliedAt?: string;
  rollbackVersion?: number;
  jobId?: string;
}

interface ConfigDialog {
  message: string;
  confirmLabel?: string;
  cancelLabel?: string;
  onConfirm?: () => void;
}

const editableVersionStatuses = new Set(['VALIDATED', 'APPROVED', 'FAILED']);

export function InternalConfigEditor() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { canManage } = usePermissions();
  const [payload, setPayload] = useState<ConfigPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState('');
  const [selectedHostId, setSelectedHostId] = useState('');
  const [selectedFileId, setSelectedFileId] = useState('');
  const [baselineProperties, setBaselineProperties] = useState<Record<string, string>>({});
  const [draftProperties, setDraftProperties] = useState<Record<string, string>>({});
  const [newKey, setNewKey] = useState('');
  const [newValue, setNewValue] = useState('');
  const [restart, setRestart] = useState(true);
  const approvalRequired = false;
  const [preview, setPreview] = useState<PreviewResult | null>(null);
  const [versions, setVersions] = useState<ConfigVersion[]>([]);
  const [dialog, setDialog] = useState<ConfigDialog | null>(null);

  const showNotice = (message: string) => setDialog({ message, confirmLabel: 'OK' });

  const fetchConfigs = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch(`/api/v1/clusters/${id}/config`);
      if (response.ok) setPayload(await response.json());
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => { void (async () => { await fetchConfigs(); })(); }, [fetchConfigs]);

  const files = payload?.staticConfigs.configFiles || [];
  const hosts = useMemo(() => {
    const unique = new Map<string, { id: string; address: string; services: number }>();
    const topo = payload?.serviceTopology || [];
    topo.forEach(service => {
      const current = unique.get(service.hostId);
      unique.set(service.hostId, {
        id: service.hostId,
        address: service.hostAddress,
        services: (current?.services || 0) + 1,
      });
    });
    return Array.from(unique.values());
  }, [payload?.serviceTopology]);

  useEffect(() => {
    Promise.resolve().then(() => {
      if (!selectedHostId && hosts[0]) setSelectedHostId(hosts[0].id);
    });
  }, [hosts, selectedHostId]);

  const hostFiles = files.filter((file: any) => !selectedHostId || file.hostId === selectedHostId);
  const selectedFile = hostFiles.find(file => file.id === selectedFileId) || hostFiles[0];

  useEffect(() => {
    Promise.resolve().then(() => {
      if (selectedFile && selectedFile.id !== selectedFileId) setSelectedFileId(selectedFile.id);
    });
  }, [selectedFile, selectedFileId]);

  useEffect(() => {
    if (!selectedFile) return;
    const properties = Object.fromEntries(
      Object.entries(selectedFile.properties || {}).map(([key, value]) => [key, String(value ?? '')])
    );
    Promise.resolve().then(() => {
      setBaselineProperties(properties);
      setDraftProperties(properties);
      setPreview(null);
    });
  }, [selectedFile]);

  const fetchVersions = useCallback(async (serviceId?: string) => {
    if (!serviceId) { setVersions([]); return; }
    const response = await fetch(`/api/v1/clusters/${id}/config/versions?serviceId=${serviceId}`);
    if (response.ok) setVersions(await response.json() as any[]);
  }, [id]);

  useEffect(() => { void (async () => { await fetchVersions(selectedFile?.serviceId); })(); }, [fetchVersions, selectedFile?.serviceId]);

  const selectHost = (hostId: string) => {
    setSelectedHostId(hostId);
    setSelectedFileId(files.find(file => file.hostId === hostId)?.id || '');
  };

  const mutateDraft = (updater: (current: Record<string, string>) => Record<string, string>) => {
    if (!canManage) return;
    setDraftProperties(current => updater(current));
    setPreview(null);
  };

  const addProperty = () => {
    if (!canManage) return;
    const key = newKey.trim();
    if (!key || !/^[A-Za-z0-9._-]+$/.test(key)) {
      showNotice('Enter a valid Kafka property key.');
      return;
    }
    mutateDraft(current => ({ ...current, [key]: newValue }));
    setNewKey('');
    setNewValue('');
  };

  const versionRequest = {
    currentProperties: baselineProperties,
    properties: draftProperties,
    configFileName: selectedFile?.path,
    approvalRequired,
    restart,
  };

  const reviewChange = async () => {
    if (!canManage) return;
    if (!selectedFile?.serviceId) return;
    setWorking('preview');
    try {
      const response = await fetch(`/api/v1/clusters/${id}/config/services/${selectedFile.serviceId}/versions/preview`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(versionRequest),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) { showNotice(data.message || 'Unable to validate configuration.'); return; }
      const localDiff: ConfigDiff[] = Array.from(new Set([
        ...Object.keys(baselineProperties),
        ...Object.keys(draftProperties),
      ])).flatMap(key => {
        const oldValue = baselineProperties[key];
        const newValue = draftProperties[key];
        if (oldValue === newValue) return [];
        return [{
          key,
          type: oldValue === undefined ? 'ADDED' : newValue === undefined ? 'REMOVED' : 'MODIFIED',
          oldValue: oldValue ?? '',
          newValue: newValue ?? '',
        } as ConfigDiff];
      });
      setPreview({ ...data, diff: Array.isArray(data.diff) && data.diff.length > 0 ? data.diff : localDiff });
    } finally {
      setWorking('');
    }
  };

  const saveVersion = async () => {
    if (!canManage) return;
    if (!selectedFile?.serviceId || !preview?.valid) return;
    setWorking('save');
    try {
      const response = await fetch(`/api/v1/clusters/${id}/config/services/${selectedFile.serviceId}/versions`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(versionRequest),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) { showNotice(data.message || 'Unable to save configuration version.'); return; }
      await fetchVersions(selectedFile.serviceId);
      showNotice(`Version v${data.configVersion} saved. The active production file has not been changed.`);
    } finally {
      setWorking('');
    }
  };

  const performVersionAction = async (version: ConfigVersion, action: 'apply' | 'rollback') => {
    if (!canManage) return;
    setWorking(`${action}-${version.id}`);
    try {
      const response = await fetch(`/api/v1/clusters/${id}/config/versions/${version.id}/${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: action === 'apply' ? JSON.stringify({ restart }) : undefined,
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) { showNotice(data.message || `${action} failed.`); return; }
      await fetchVersions(selectedFile?.serviceId);
      if (action === 'apply' && data.jobId) {
        showNotice('The configuration apply job has started. View job is now available in Version History.');
      }
      if (action === 'rollback') {
        showNotice(`Rollback saved as new version v${data.configVersion}. Approve it if required, then apply it.`);
      }
    } finally {
      setWorking('');
    }
  };

  const versionAction = (version: ConfigVersion, action: 'apply' | 'rollback') => {
    if (action !== 'apply') {
      void performVersionAction(version, action);
      return;
    }
    const message = restart
      ? `Apply configuration v${version.configVersion} and perform a controlled rolling service restart? Kafka on the affected node will be restarted and verified by the job.`
      : `Apply configuration v${version.configVersion} without restarting Kafka? Static properties will not become active until a later restart.`;
    setDialog({
      message,
      cancelLabel: 'Cancel',
      confirmLabel: 'OK',
      onConfirm: () => { setDialog(null); void performVersionAction(version, action); },
    });
  };

  const latestApplyableVersion = useMemo(() => {
    return [...versions]
      .sort((a, b) => b.configVersion - a.configVersion)
      .find(v => editableVersionStatuses.has(v.status));
  }, [versions]);

  if (loading && !payload) {
    return <div className="state-center"><Loader2 className="spin" /> Loading node configurations...</div>;
  }

  const activeVersion = versions.find(version => version.status === 'APPLIED');

  const flowButtonStyle = (disabled: boolean) => ({
    display: 'inline-flex',
    alignItems: 'center',
    gap: '6px',
    padding: '6px 12px',
    border: '1px solid #7C3AED',
    borderRadius: '6px',
    background: '#fff',
    color: '#7C3AED',
    fontWeight: 650,
    fontSize: '12px',
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.5 : 1,
    transition: 'all 0.2s',
  });

  return (
    <div className="node-config-page versioned-config-page">
      <header className="node-config-header">
        <div><h2>Versioned Configuration Change</h2><p>Review, validate and save an immutable version before anything reaches a node.</p></div>
        <button onClick={fetchConfigs} disabled={loading} aria-label="Refresh configuration" title="Refresh"><RefreshCw size={14} className={loading ? 'spin' : ''} /></button>
      </header>

      <div className="config-flow-strip" style={{
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        background: 'none',
        border: 'none',
        padding: '0px',
        marginBottom: '1.25rem'
      }}>
        <button 
          onClick={reviewChange} 
          disabled={!!working || !selectedFile?.serviceId} 
          style={flowButtonStyle(!!working || !selectedFile?.serviceId)}
        >
          <GitCompare size={14} /> Diff
        </button>
        <button 
          onClick={reviewChange} 
          disabled={!!working || !selectedFile?.serviceId} 
          style={flowButtonStyle(!!working || !selectedFile?.serviceId)}
        >
          <FileCheck size={14} /> Validate
        </button>
        <button 
          onClick={saveVersion} 
          disabled={!preview?.valid || !!working} 
          style={flowButtonStyle(!preview?.valid || !!working)}
        >
          <Download size={14} /> Save version
        </button>
        <button 
          onClick={() => latestApplyableVersion && versionAction(latestApplyableVersion, 'apply')} 
          disabled={!latestApplyableVersion || !!working} 
          style={flowButtonStyle(!latestApplyableVersion || !!working)}
        >
          <UploadCloud size={14} /> Backup &amp; apply
        </button>
      </div>

      <section className="node-config-section config-selection-step">
        <div className="node-config-section-title">
          <span style={{ border: '1px solid #7C3AED', background: '#fff', color: '#7C3AED' }}>1</span>
          <div><h3>Select node</h3><p>Each VM may contain one or more Kafka services.</p></div>
        </div>
        <div className="node-config-hosts">
          {hosts.map(host => (
            <button 
              key={host.id} 
              className={selectedHostId === host.id ? 'active' : ''} 
              onClick={() => selectHost(host.id)}
              style={selectedHostId === host.id ? {
                background: '#FAF5FF',
                borderColor: '#D8B4FE',
                color: '#6B21A8'
              } : {}}
            >
              <Server size={16} /><span><strong>{host.address}</strong><small>{host.id} - {host.services} service{host.services === 1 ? '' : 's'}</small></span>
            </button>
          ))}
        </div>
      </section>

      <section className="node-config-section config-selection-step">
        <div className="node-config-section-title">
          <span style={{ border: '1px solid #7C3AED', background: '#fff', color: '#7C3AED' }}>2</span>
          <div><h3>Select Configuration File</h3><p>Only files belonging to the selected node are shown.</p></div>
        </div>
        <div className="node-config-files">
          {hostFiles.map(file => (
            <button 
              key={file.id} 
              className={selectedFile?.id === file.id ? 'active' : ''} 
              onClick={() => setSelectedFileId(file.id)}
              style={selectedFile?.id === file.id ? {
                background: '#FAF5FF',
                borderColor: '#D8B4FE',
                color: '#6B21A8'
              } : {}}
            >
              <Server size={16} /><span><strong>{file.label}</strong><small>{file.path}</small></span>
            </button>
          ))}
        </div>
      </section>

      {selectedFile ? <>
        <section className="node-config-section editor">
          <div className="node-config-editor-head">
            <div><h3>{selectedFile.label}</h3><p>{selectedFile.path}</p></div>
            <div className="config-options">
              {canManage && <label><input type="checkbox" checked={restart} onChange={event => { setRestart(event.target.checked); setPreview(null); }} /> Restart after apply</label>}
            </div>
          </div>

          <div className="node-config-table-wrap">
            <table className="node-config-table">
              <thead><tr><th>Property</th><th>Value</th><th>Action</th></tr></thead>
              <tbody>
                {Object.entries(draftProperties).sort(([a], [b]) => a.localeCompare(b)).map(([key, value]) => {
                  return <tr key={key}>
                    <td><code>{key}</code></td>
                    <td><input value={value} disabled={!canManage} onChange={event => mutateDraft(current => ({ ...current, [key]: event.target.value }))} style={{ border: '1px solid #e2e8f0', borderRadius: '6px' }} /></td>
                    <td>{canManage && <button title={`Remove ${key}`} onClick={() => mutateDraft(current => { const next = { ...current }; delete next[key]; return next; })} style={{ border: '1px solid #fee2e2', color: '#ef4444', background: '#fff' }}><Trash2 size={14} /></button>}</td>
                  </tr>;
                })}
              </tbody>
            </table>
          </div>

          {canManage && (
            <div className="node-config-add" style={{ display: 'grid', gridTemplateColumns: 'minmax(180px, 0.8fr) minmax(220px, 1.2fr) auto', gap: '8px', marginTop: '1rem' }}>
              <input 
                placeholder="property.key" 
                value={newKey} 
                onChange={event => setNewKey(event.target.value)} 
                style={{ border: '1px solid #e2e8f0', borderRadius: '8px', padding: '8px 12px' }}
              />
              <input 
                placeholder="value" 
                value={newValue} 
                onChange={event => setNewValue(event.target.value)} 
                style={{ border: '1px solid #e2e8f0', borderRadius: '8px', padding: '8px 12px' }}
              />
              <button 
                onClick={addProperty}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '6px',
                  padding: '8px 16px',
                  borderRadius: '8px',
                  border: '1px solid #3E1363',
                  background: '#fff',
                  color: '#3E1363',
                  fontWeight: 500,
                  fontSize: '13px',
                  cursor: 'pointer'
                }}
              >
                <Plus size={14} /> Add property
              </button>
            </div>
          )}

          <div className="node-config-footer" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem' }}>
            <span style={{ fontSize: '12px', color: '#64748b' }}>
              Target: {selectedFile.hostId}Node: {selectedFile.nodeId}Service: {selectedFile.role}
            </span>
            {canManage && (
              <button 
                onClick={reviewChange} 
                disabled={!!working}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '6px',
                  height: '38px',
                  padding: '0 20px',
                  borderRadius: '8px',
                  background: '#3E1363',
                  color: '#fff',
                  border: 'none',
                  fontSize: '13px',
                  fontWeight: 500,
                  cursor: working ? 'not-allowed' : 'pointer'
                }}
              >
                {working === 'preview' ? <Loader2 size={14} className="spin" /> : <RefreshCw size={14} />} 
                Review &amp; validate
              </button>
            )}
          </div>
        </section>

        <section className="node-config-section config-review" style={{ borderColor: '#e2e8f0', marginTop: '1.5rem' }}>
          <div className="node-config-section-title">
            <span style={{ border: '1px solid #7C3AED', background: '#fff', color: '#7C3AED' }}>3</span>
            <div><h3>Old vs New</h3><p>The server validates this exact snapshot again when the version is saved.</p></div>
          </div>
          {preview ? <>
          {preview.errors.length > 0 && <div className="config-messages error">{preview.errors.map(message => <p key={message}>{message}</p>)}</div>}
          {preview.warnings.length > 0 && <div className="config-messages warning">{preview.warnings.map(message => <p key={message}>{message}</p>)}</div>}
          <div className="config-diff-list">
            {preview.diff.map(item => (
              <div className="config-diff-item" key={item.key}>
                <div className="config-diff-meta">
                  <span>{item.type}</span>
                  <strong>{item.key}</strong>
                </div>
                <div className="config-diff-values">
                  <div>{item.oldValue || 'empty'}</div>
                  <div>{item.newValue || 'empty'}</div>
                </div>
              </div>
            ))}
          </div>
          <div className="config-review-footer" style={{ marginTop: '20px', borderTop: '1px solid #f1f5f9', paddingTop: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '12px', color: '#64748b' }}>{preview.valid ? 'Validation passed. Saving creates history only; it does not apply the file.' : 'Fix validation errors before saving.'}</span>
            {canManage && (
              <button 
                onClick={saveVersion} 
                disabled={!preview.valid || !!working}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '6px',
                  height: '38px',
                  padding: '0 16px',
                  borderRadius: '8px',
                  background: '#3E1363',
                  color: '#fff',
                  border: 'none',
                  fontSize: '13px',
                  fontWeight: 500,
                  cursor: !preview.valid || !!working ? 'not-allowed' : 'pointer',
                  opacity: !preview.valid || !!working ? 0.5 : 1
                }}
              >
                {working === 'save' ? <Loader2 size={14} className="spin" /> : <Save size={14} />}
                Save as new Version
              </button>
            )}
          </div>
          </> : <p className="config-review-placeholder">Review and validate the draft to compare it with the saved configuration.</p>}
        </section>

        <section className="node-config-section config-history">
          <div className="node-config-section-title">
            <span>4</span>
            <div><h3>Version History</h3><p>Backups, approvals, applies and rollback lineage remain auditable.</p></div>
          </div>
          {versions.length > 0 ? (
            <div className="version-list">
              {[...versions].sort((a, b) => b.configVersion - a.configVersion).map(version => (
                <article key={version.id} className={version.id === activeVersion?.id ? 'active-version' : ''}>
                  <div className="version-main">
                    <strong>v{version.configVersion}</strong>
                    <span className={`version-status ${version.status.toLowerCase()}`}>{version.status.replaceAll('_', ' ')}</span>
                    {version.rollbackVersion != null && <span className="rollback-tag">Rollback of v{version.rollbackVersion}</span>}
                    <small>created by {version.createdBy || 'Unknown'} ┬╖ {new Date(version.createdAt).toLocaleString()}</small>
                  </div>
                  <div className="version-actions">
                    {version.status !== 'APPLIED' && canManage ? (
                      <button
                        type="button"
                        className="primary"
                        disabled={!!working}
                        onClick={() => versionAction(version, 'apply')}
                      >
                        {working === `apply-${version.id}` ? <Loader2 size={14} className="spin" /> : <UploadCloud size={14} />} Apply
                      </button>
                    ) : version.status === 'APPLIED' ? (
                      <button type="button" className="view-job highlighted" onClick={() => navigate('/jobs')}>View job</button>
                    ) : null}
                  </div>
                </article>
              ))}
            </div>
          ) : (
            <p className="version-history-empty">No saved configuration versions yet.</p>
          )}
        </section>
      </> : <div className="empty-state">No managed configuration file is available for this node.</div>}

      {dialog && (
        <div className="config-dialog-backdrop" role="dialog" aria-modal="true" aria-labelledby="config-dialog-title">
          <div className="config-dialog">
            <div className="config-dialog-banner">
              <button
                type="button"
                className="config-dialog-close"
                aria-label="Close dialog"
                onClick={() => setDialog(null)}
              >
                <X size={22} />
              </button>
            </div>
            <div className="config-dialog-body">
              <h3 id="config-dialog-title">{window.location.host} says</h3>
              <p>{dialog.message}</p>
              <div className="config-dialog-actions">
                {dialog.cancelLabel && (
                  <button type="button" className="cancel" onClick={() => setDialog(null)}>{dialog.cancelLabel}</button>
                )}
                <button
                  type="button"
                  className="confirm"
                  onClick={() => dialog.onConfirm ? dialog.onConfirm() : setDialog(null)}
                >
                  {dialog.confirmLabel || 'OK'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { AlertTriangle, RefreshCw, Check, Server } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { CustomSelect } from '../components/CustomSelect';
import { AnchoredMenu } from '../components/AnchoredMenu';
import './Monitoring.css';

interface MonitoringNode {
  nodeId?: string | null;
  hostId?: string | null;
  hostname?: string | null;
  hostIp?: string | null;
  role?: string | null;
}

interface MonitoringCluster {
  id: string;
  name: string;
  originType: 'INTERNAL' | 'EXTERNAL' | string;
  monitoringEnabled: boolean;
  kafkaExporterTarget?: string;
  jmxAvailable?: boolean;
  warning?: string;
  nodes?: MonitoringNode[];
}

interface MonitoringOverview {
  clusterId: string;
  name: string;
  originType: string;
  prometheusUrl?: string;
  kafkaExporterTarget?: string;
  jmxAvailable?: boolean;
  kafkaExporterUp?: number | null;
  jmxUp?: number | null;
  kafkaExporterUpTargets?: number | null;
  kafkaExporterTotalTargets?: number | null;
  jmxUpTargets?: number | null;
  jmxTotalTargets?: number | null;
  brokerCount?: number | null;
  topicCount?: number | null;
  partitionCount?: number | null;
  underReplicatedPartitions?: number | null;
  consumerLag?: number | null;
  messagesInPerSecond?: number | null;
  bytesInPerSecond?: number | null;
  bytesOutPerSecond?: number | null;
  jvmHeapUsedPercent?: number | null;
  jvmHeapAvailableBytes?: number | null;
  jvmHeapTotalBytes?: number | null;
  brokerCpuPercent?: number | null;
  jvmProcessCpuPercent?: number | null;
  systemCpuPercent?: number | null;
  warnings?: string[];
  hostMemoryUsedPercent?: number | null;
  hostMemoryAvailableMb?: number | null;
  hostMemoryTotalMb?: number | null;
  selectedNodeId?: string | null;
  nodes?: MonitoringNode[];
}

interface MonitoringSample {
  time: string;
  brokers: number | null;
  topics: number | null;
  partitions: number | null;
  underReplicated: number | null;
  lag: number | null;
  messagesIn: number | null;
  bytesIn: number | null;
  bytesOut: number | null;
  heap: number | null;
  hostMemory: number | null;
  brokerCpu: number | null;
  systemCpu: number | null;
}

const formatNumber = (value?: number | null, digits = 0) => {
  if (value === undefined || value === null || Number.isNaN(value)) return 'N/A';
  return value.toLocaleString(undefined, { maximumFractionDigits: digits, minimumFractionDigits: digits });
};

const formatBytes = (value?: number | null) => {
  if (value === undefined || value === null || Number.isNaN(value)) return 'N/A';
  if (value <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let next = value;
  let unit = 0;
  while (next >= 1024 && unit < units.length - 1) {
    next /= 1024;
    unit += 1;
  }
  return `${next.toFixed(unit === 0 ? 0 : 2)} ${units[unit]}`;
};

const hasValue = (value?: number | null) => value !== undefined && value !== null && !Number.isNaN(value);

const chartNumber = (value?: number | null) => hasValue(value) ? Number(value) : null;

const nodeValue = (node: MonitoringNode) => String(node.nodeId || '');

const nodeLabel = (node: MonitoringNode) => {
  const nodeName = node.nodeId ? `Node ${node.nodeId}` : 'Node';
  const host = node.hostname || node.hostIp;
  const role = node.role;
  return [nodeName, role, host].filter(Boolean).join(' ┬╖ ');
};

export function Monitoring() {
  const [selectedType, setSelectedType] = useState<'INTERNAL' | 'EXTERNAL'>('INTERNAL');
  const [clusters, setClusters] = useState<MonitoringCluster[]>([]);
  const [selectedClusterId, setSelectedClusterId] = useState('');
  const [selectedNodeId, setSelectedNodeId] = useState('');
  const [nodes, setNodes] = useState<{ value: string, label: string, role?: string | null }[]>([]);

  const [overview, setOverview] = useState<MonitoringOverview | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [refreshInterval, setRefreshInterval] = useState(10); // Default 10 seconds
  const [history, setHistory] = useState<MonitoringSample[]>([]);
  const [showIntervalDropdown, setShowIntervalDropdown] = useState(false);
  const [liveDropdownAnchor, setLiveDropdownAnchor] = useState<HTMLDivElement | null>(null);
  const selectedCluster = useMemo(() => clusters.find(c => c.id === selectedClusterId), [clusters, selectedClusterId]);

  // Load nodes when selectedClusterId changes
  useEffect(() => {
    Promise.resolve().then(() => {
      if (!selectedClusterId && !selectedCluster) {
        setNodes([]);
        setSelectedNodeId('');
        return;
      }
    });
    const formatted = (selectedCluster.nodes || [])
      .filter(node => Boolean(nodeValue(node)))
      .map(node => ({ value: nodeValue(node), label: nodeLabel(node), role: node.role }));
    Promise.resolve().then(() => {
      setNodes(formatted);
      setSelectedNodeId(current => formatted.some(node => node.value === current) ? current : (formatted[0]?.value || ''));
    });
  }, [selectedCluster]);


  // 1. Load clusters and hosts on mount
  const loadInitialData = useCallback(async () => {
    if (!selectedType) {
      setClusters([]);
      setSelectedClusterId('');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const clustersRes = await fetch(`/api/v1/monitoring/clusters?type=${selectedType}`);
      let clusterList: MonitoringCluster[] = [];
      if (clustersRes.ok) {
        clusterList = await clustersRes.json();
        setClusters(clusterList);
      }

      setSelectedClusterId(current =>
        clusterList.some(cluster => cluster.id === current)
          ? current
          : (clusterList[0]?.id || '')
      );
    } catch (err: unknown) {
      console.error(err);
      setError('Failed to load initial monitoring data.');
    } finally {
      setLoading(false);
    }
  }, [selectedType]);

  useEffect(() => {
    Promise.resolve().then(() => {
      setOverview(null);
      setHistory([]);
      setSelectedNodeId('');
    });
    void (async () => { await loadInitialData(); })();
  }, [selectedType, loadInitialData]);



  // Fetch overview metrics for the selected cluster
  const loadOverview = useCallback(async (silent = false) => {
    if (!selectedClusterId && !selectedCluster) return;

    if (!silent) setLoading(true);
    try {
      // 1. Fetch Prometheus Metrics
      const params = new URLSearchParams();
      if (selectedNodeId) {
        params.set('nodeId', selectedNodeId);
      }
      const query = params.toString();
      const res = await fetch(`/api/v1/monitoring/clusters/${selectedClusterId}/overview${query ? `?${query}` : ''}`);
      if (res.ok) {
        const data = await res.json();
        setOverview(data);
      }

    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  }, [selectedClusterId, selectedNodeId]);

  useEffect(() => {
    if (selectedClusterId) {
      Promise.resolve().then(() => setHistory([]));
      void (async () => { await loadOverview(); })();
    }
  }, [selectedClusterId, loadOverview]);

  // Append sample to history when overview updates
  useEffect(() => {
    if (!overview) return;
    Promise.resolve().then(() => {
      setHistory(current => {
      const next: MonitoringSample = {
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        brokers: chartNumber(overview.brokerCount),
        topics: chartNumber(overview.topicCount),
        partitions: chartNumber(overview.partitionCount),
        underReplicated: chartNumber(overview.underReplicatedPartitions),
        lag: chartNumber(overview.consumerLag),
        messagesIn: chartNumber(overview.messagesInPerSecond),
        bytesIn: chartNumber(overview.bytesInPerSecond),
        bytesOut: chartNumber(overview.bytesOutPerSecond),
        heap: chartNumber(overview.jvmHeapUsedPercent),
        hostMemory: chartNumber(overview.hostMemoryUsedPercent),
        brokerCpu: chartNumber(overview.jvmProcessCpuPercent ?? overview.brokerCpuPercent),
        systemCpu: chartNumber(overview.systemCpuPercent),
      };
      return [...current, next].slice(-15); // keep 15 samples
      });
    });
  }, [overview]);

  // Auto refresh loop
  useEffect(() => {
    if (!autoRefresh || !selectedClusterId) return;
    const timer = window.setInterval(() => {
      if (!document.hidden) {
        loadOverview(true);
      }
    }, refreshInterval * 1000);
    return () => window.clearInterval(timer);
  }, [autoRefresh, refreshInterval, loadOverview, selectedClusterId]);

  // Mock initial history if empty to generate pretty graphs immediately
  const graphHistory = history;
  const clusterTitle = overview?.name || selectedCluster?.name || 'Select a cluster';
  const exporterTarget = overview?.kafkaExporterTarget || selectedCluster?.kafkaExporterTarget;
  const selectedNode = nodes.find(node => node.value === selectedNodeId);
  const kafkaExporterHealthy = hasValue(overview?.kafkaExporterTotalTargets)
    && Number(overview?.kafkaExporterTotalTargets) > 0
    && Number(overview?.kafkaExporterUpTargets) === Number(overview?.kafkaExporterTotalTargets);
  const kafkaExporterStatus = targetHealthStatus(
    overview?.kafkaExporterUpTargets,
    overview?.kafkaExporterTotalTargets
  );
  const jmxStatus = targetHealthStatus(overview?.jmxUpTargets, overview?.jmxTotalTargets);
  const kafkaRunning = Boolean(overview) && (kafkaExporterHealthy || (overview?.brokerCount || 0) > 0);
  const warningMessages = [
    selectedCluster?.warning,
    ...(overview?.warnings || []),
  ].filter((message): message is string => Boolean(message && message.trim()));
  const selectedRole = selectedNode?.role || '';
  const controllerOnlySelected = selectedRole.toLowerCase().includes('controller')
    && !selectedRole.toLowerCase().includes('broker');
  const combinedRoleSelected = selectedRole.toLowerCase().includes('controller')
    && selectedRole.toLowerCase().includes('broker');
  const brokerMetricsApplicable = !controllerOnlySelected;
  const jvmRoleLabel = controllerOnlySelected
    ? 'Controller JVM'
    : (combinedRoleSelected ? 'Broker + Controller JVM' : 'Broker JVM');
  const jmxTargetLabel = controllerOnlySelected
    ? 'Controller JMX'
    : (combinedRoleSelected ? 'Broker + Controller JMX' : 'Broker JMX');
  const visibleWarnings = warningMessages.filter(message => !(
    controllerOnlySelected && message.toLowerCase().includes('kafka exporter')
  ));
  const displayCpuUsage = overview?.jvmProcessCpuPercent ?? overview?.brokerCpuPercent ?? overview?.systemCpuPercent;
  const displayMemoryUsage = overview?.jvmHeapUsedPercent ?? overview?.hostMemoryUsedPercent;
  const cpuUsageLabel = hasValue(overview?.jvmProcessCpuPercent ?? overview?.brokerCpuPercent)
    ? `${jvmRoleLabel} CPU`
    : 'Host CPU Usage';
  const memoryUsageLabel = hasValue(overview?.jvmHeapUsedPercent)
    ? `${jvmRoleLabel} Heap`
    : 'Host Memory Usage';

  return (
    <div className="monitoring-container animate-fade-in">
      <div className="monitoring-white-box">
        {/* Header Section */}
        <div className="header-section">
          <div className="title-area">
            <div>
              <h1>Monitoring</h1>
              <p className="subtitle">Real-time Kafka & system metrics</p>
            </div>
          </div>

          {/* Controls */}
          <div className="controls-area">
            <div className="monitoring-control-field monitoring-type-field">
              <span>Cluster type</span>
              <CustomSelect
                value={selectedType}
                onChange={val => {
                  setSelectedType(val as 'INTERNAL' | 'EXTERNAL');
                  setSelectedClusterId('');
                }}
                options={[
                  { value: 'INTERNAL', label: 'Internal' },
                  { value: 'EXTERNAL', label: 'External' },
                ]}
                width="154px"
                placeholder="Select Type"
              />
            </div>


            {/* CLUSTER NAME Selector */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
              <span style={{ fontSize: '11px', fontWeight: 700, color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                Cluster Name
              </span>
              <CustomSelect
                value={selectedClusterId}
                onChange={val => {
                  setSelectedClusterId(val);
                  setSelectedNodeId('');
                  setOverview(null);
                  setHistory([]);
                }}
                options={clusters.length > 0 ? clusters.map(c => ({ value: c.id, label: c.name })) : [{ value: '', label: 'No clusters found' }]}
                width="160px"
                placeholder="Select Cluster"
              />
            </div>

            {/* NODE NAME Selector */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
              <span style={{ fontSize: '11px', fontWeight: 700, color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                Node Name
              </span>
              <CustomSelect
                value={selectedNodeId}
                onChange={val => setSelectedNodeId(val)}
                options={nodes}
                width="min(360px, 100%)"
                placeholder="Select Node"
              />
            </div>

            {/* Live indicator Pill Box */}
            <div ref={setLiveDropdownAnchor} className="live-pill-dropdown-wrapper" style={{ height: '40px', display: 'flex', alignItems: 'center' }}>
              <div
                className={`live-pill-container ${autoRefresh ? 'active' : ''}`}
                onClick={() => setShowIntervalDropdown(!showIntervalDropdown)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  background: '#F8FAFC',
                  border: '1px solid #E2E8F0',
                  borderRadius: '8px',
                  padding: '8px 12px',
                  cursor: 'pointer',
                  userSelect: 'none',
                  height: '40px',
                  boxSizing: 'border-box'
                }}
              >
                <span style={{
                  width: '8px',
                  height: '8px',
                  borderRadius: '50%',
                  background: autoRefresh ? '#10B981' : '#94A3B8',
                  display: 'inline-block'
                }}></span>
                <span style={{ fontSize: '14px', fontWeight: 600, color: '#334155' }}>Live</span>
                <div
                  style={{
                    width: '16px',
                    height: '16px',
                    borderRadius: '4px',
                    border: '1px solid #CBD5E1',
                    background: autoRefresh ? '#3B82F6' : '#fff',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    marginLeft: '4px'
                  }}
                >
                  {autoRefresh && <Check size={12} strokeWidth={3} color="#fff" />}
                </div>
              </div>

              {showIntervalDropdown && liveDropdownAnchor && (
                <AnchoredMenu
                  anchor={liveDropdownAnchor}
                  className="live-dropdown-menu"
                  onClose={() => setShowIntervalDropdown(false)}
                  align="start"
                  minWidth={180}
                >
                  {[5, 10, 15, 30, 60].map((sec) => (
                    <div
                      key={sec}
                      className={`live-dropdown-item ${refreshInterval === sec && autoRefresh ? 'selected' : ''}`}
                      onClick={() => {
                        setRefreshInterval(sec);
                        setAutoRefresh(true);
                        setShowIntervalDropdown(false);
                      }}
                    >
                      <span className="live-pill-dot active"></span>
                      Live | {sec} Sec
                    </div>
                  ))}
                  <div className="dropdown-divider" />
                  <div
                    className={`live-dropdown-item ${!autoRefresh ? 'paused' : ''}`}
                    onClick={() => {
                      setAutoRefresh(!autoRefresh);
                      setShowIntervalDropdown(false);
                    }}
                  >
                    <span className="live-pill-dot"></span>
                    {autoRefresh ? 'Pause Live Feed' : 'Resume Live Feed'}
                  </div>
                </AnchoredMenu>
              )}
            </div>

            {/* Refresh interval status display */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              background: '#F8FAFC',
              border: '1px solid #E2E8F0',
              borderRadius: '8px',
              padding: '8px 16px',
              height: '40px',
              fontSize: '14px',
              fontWeight: 600,
              color: '#334155',
              boxSizing: 'border-box'
            }}>
              {refreshInterval} Sec
            </div>

            {/* Manual Refresh Button */}
            <button
              className="manual-refresh-button"
              onClick={() => {
                if (selectedClusterId) {
                  loadOverview();
                } else {
                  loadInitialData();
                }
              }}
              disabled={loading}
              style={{
                height: '40px',
                width: '40px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                border: '1px solid #E2E8F0',
                borderRadius: '8px',
                background: '#fff',
                cursor: 'pointer'
              }}
            >
              <RefreshCw size={18} className={loading ? 'spin' : ''} />
            </button>
          </div>
        </div>

        {selectedClusterId === '' ? (
          <div className="monitoring-empty-state-card">
            <div className="monitoring-empty-illustration">
              <svg width="120" height="96" viewBox="0 0 120 96" fill="none" xmlns="http://www.w3.org/2000/svg">
                {/* Card 1 */}
                <g filter="url(#shadow-1)">
                  <rect x="10" y="2" width="100" height="24" rx="6" fill="white" stroke="#E2E8F0" strokeWidth="1.5" />
                  <rect x="22" y="12" width="16" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                  <rect x="46" y="12" width="40" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                </g>

                {/* Card 2 */}
                <g filter="url(#shadow-2)">
                  <rect x="10" y="34" width="100" height="24" rx="6" fill="white" stroke="#E2E8F0" strokeWidth="1.5" />
                  <rect x="22" y="44" width="36" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                  <rect x="66" y="44" width="20" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                </g>

                {/* Card 3 */}
                <g filter="url(#shadow-3)">
                  <rect x="10" y="66" width="100" height="24" rx="6" fill="white" stroke="#E2E8F0" strokeWidth="1.5" />
                  <rect x="22" y="76" width="12" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                  <rect x="42" y="76" width="30" height="4" rx="2" fill="#8E77BB" fillOpacity="0.4" />
                </g>

                <defs>
                  <filter id="shadow-1" x="6" y="0" width="108" height="32" filterUnits="userSpaceOnUse" colorInterpolationFilters="sRGB">
                    <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor="#0F172A" floodOpacity="0.04" />
                  </filter>
                  <filter id="shadow-2" x="6" y="32" width="108" height="32" filterUnits="userSpaceOnUse" colorInterpolationFilters="sRGB">
                    <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor="#0F172A" floodOpacity="0.04" />
                  </filter>
                  <filter id="shadow-3" x="6" y="64" width="108" height="32" filterUnits="userSpaceOnUse" colorInterpolationFilters="sRGB">
                    <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor="#0F172A" floodOpacity="0.04" />
                  </filter>
                </defs>
              </svg>
            </div>
            <h2>Select a cluster to monitor</h2>
            <p>Choose a cluster from the dropdown above to display its real-time metrics and nodes.</p>
          </div>
        ) : (
          <>
            {error && (
              <div className="error-banner">
                <p>{error}</p>
              </div>
            )}

            {visibleWarnings.length > 0 && (
              <div className="monitoring-warning-list">
                {visibleWarnings.map(message => (
                  <div className="monitoring-warning" key={message}>
                    <AlertTriangle size={16} />
                    <span>{message}</span>
                  </div>
                ))}
              </div>
            )}

            {/* Broker Details Header Card */}
            <div className="broker-details-card">
              <div style={{ display: 'flex', alignItems: 'center', gap: '18px' }}>
                <Server size={28} color="#DF678B" style={{ flexShrink: 0 }} />
                <div className="broker-info">
                  <h2 style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                    {clusterTitle}
                    <span className={`cluster-source-tag ${kafkaRunning ? 'state-positive' : 'state-negative'}`}>
                      {selectedType === 'INTERNAL' ? 'Internal' : 'External'}
                    </span>
                  </h2>
                  <p className="broker-meta">
                    {[exporterTarget?.split(':')[0], selectedNode?.label].filter(Boolean).join(' | ') || 'Monitoring endpoint unavailable'}
                  </p>
                </div>
              </div>
              <div className="monitoring-status-right">
                <span className={`kafka-running-badge ${kafkaRunning ? 'state-positive' : 'state-negative'}`}>
                  <span className="status-dot"></span>
                  {kafkaRunning ? 'Kafka running' : 'Kafka offline'}
                </span>
              </div>
            </div>

            <div className="monitoring-data-panel">
              {/* Real-time Performance Section */}
              <div className="section-header-row">
                <div className="performance-header-left">
                  <h3>Real-time Performance</h3>
                  <span className="live-performance-badge">
                    Live
                  </span>
                </div>
                <div className="monitoring-status-pills-row">
                  {brokerMetricsApplicable && (
                    <span className={`monitoring-connection-pill ${kafkaExporterStatus.state}`}>
                      {targetHealthLabel('Kafka Exporter', kafkaExporterStatus)}
                    </span>
                  )}
                  <span className={`monitoring-connection-pill ${jmxStatus.state}`}>
                    {targetHealthLabel(jmxTargetLabel, jmxStatus)}
                  </span>
                </div>
              </div>

              <div className="performance-section-card">
                <div className="charts-grid-row">
                  {/* CPU Usage Chart */}
                  <div className="chart-box-wrapper">
                    <div className="chart-box-header">
                      <span>{cpuUsageLabel}</span>
                      <span className="chart-stat-value green">
                        {hasValue(displayCpuUsage) ? `${formatNumber(displayCpuUsage, 1)}%` : 'N/A'}
                      </span>
                    </div>
                    <div className="chart-body-container">
                      <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={graphHistory} margin={{ top: 5, right: 5, left: -25, bottom: 5 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                          <XAxis dataKey="time" tick={{ fontSize: 9, fill: '#94a3b8' }} />
                          <YAxis tick={{ fontSize: 9, fill: '#94a3b8' }} domain={[0, 100]} />
                          <Tooltip contentStyle={{ fontSize: '11px', borderRadius: '6px' }} />
                          <Line type="monotone" dataKey="brokerCpu" stroke="#3b82f6" strokeWidth={1.5} dot={false} activeDot={{ r: 4 }} />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* Memory Usage Chart */}
                  <div className="chart-box-wrapper">
                    <div className="chart-box-header">
                      <span>{memoryUsageLabel}</span>
                      <span className="chart-stat-value green">
                        {hasValue(displayMemoryUsage) ? `${formatNumber(displayMemoryUsage, 1)}%` : 'N/A'}
                      </span>
                    </div>
                    <div className="chart-body-container">
                      <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={graphHistory} margin={{ top: 5, right: 5, left: -25, bottom: 5 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                          <XAxis dataKey="time" tick={{ fontSize: 9, fill: '#94a3b8' }} />
                          <YAxis tick={{ fontSize: 9, fill: '#94a3b8' }} domain={[0, 100]} />
                          <Tooltip contentStyle={{ fontSize: '11px', borderRadius: '6px' }} />
                          <Line type="monotone" dataKey="heap" stroke="#10b981" strokeWidth={1.5} dot={false} activeDot={{ r: 4 }} />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* Messages In is a broker metric and does not apply to controller-only nodes. */}
                  {brokerMetricsApplicable && (
                    <div className="chart-box-wrapper">
                      <div className="chart-box-header">
                        <span>Messages In</span>
                        <span className="chart-stat-value red">
                          {hasValue(overview?.messagesInPerSecond) ? `${formatNumber(overview?.messagesInPerSecond, 1)}/s` : 'N/A'}
                        </span>
                      </div>
                      <div className="chart-body-container">
                        <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={graphHistory} margin={{ top: 5, right: 5, left: -25, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                            <XAxis dataKey="time" tick={{ fontSize: 9, fill: '#94a3b8' }} />
                            <YAxis tick={{ fontSize: 9, fill: '#94a3b8' }} />
                            <Tooltip contentStyle={{ fontSize: '11px', borderRadius: '6px' }} />
                            <Area type="monotone" dataKey="messagesIn" stroke="#c084fc" fill="#f3e8ff" strokeWidth={1.5} />
                          </AreaChart>
                        </ResponsiveContainer>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Kafka broker traffic is not exposed by controller-only nodes. */}
              {brokerMetricsApplicable && (
                <div className="monitoring-bottom-section">
                  <h3 className="monitoring-section-title-custom">Kafka Broker</h3>
                  <div className="monitoring-kpi-row">
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">MSG IN/Sec</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.messagesInPerSecond, 2)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Bytes IN/Sec</span>
                    <strong className="kpi-card-val">{formatBytes(overview?.bytesInPerSecond)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Bytes Out/Sec</span>
                    <strong className="kpi-card-val">{formatBytes(overview?.bytesOutPerSecond)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Partition</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.partitionCount)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Under-replication</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.underReplicatedPartitions)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Consumer Lag</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.consumerLag)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Broker</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.brokerCount)}</strong>
                  </div>
                  <div className="kpi-card-box">
                    <span className="kpi-card-label">Topics</span>
                    <strong className="kpi-card-val">{formatNumber(overview?.topicCount)}</strong>
                  </div>
                  </div>
                </div>
              )}

              {/* System Resources Section */}
              <div className="monitoring-bottom-section">
                <h3 className="monitoring-section-title-custom">System Resources</h3>
                <div className="resources-cards-grid">
                  <ResourceCard
                    label={`${jvmRoleLabel} CPU`}
                    value={overview?.jvmProcessCpuPercent ?? overview?.brokerCpuPercent}
                    tone="purple"
                    subtext={availablePercentText(overview?.jvmProcessCpuPercent ?? overview?.brokerCpuPercent)}
                  />
                  <ResourceCard
                    label="System CPU"
                    value={overview?.systemCpuPercent}
                    tone="green"
                    subtext={availablePercentText(overview?.systemCpuPercent)}
                  />
                  <ResourceCard
                    label="JVM Heap"
                    value={overview?.jvmHeapUsedPercent}
                    tone="purple"
                    subtext={hasValue(overview?.jvmHeapAvailableBytes)
                      ? availableCapacityText(
                          Number(overview?.jvmHeapAvailableBytes),
                          overview?.jvmHeapTotalBytes
                        )
                      : undefined}
                  />
                  <ResourceCard
                    label="Host Memory (Agent Heartbeat)"
                    value={overview?.hostMemoryUsedPercent}
                    tone="blue"
                    subtext={hasValue(overview?.hostMemoryAvailableMb)
                      ? availableCapacityText(
                          Number(overview?.hostMemoryAvailableMb) * 1024 * 1024,
                          hasValue(overview?.hostMemoryTotalMb)
                            ? Number(overview?.hostMemoryTotalMb) * 1024 * 1024
                            : undefined
                        )
                      : undefined}
                  />
                </div>
              </div>
            </div>
          </>
        )}

      </div>
    </div>
  );
}

const boundedPercent = (value?: number | null) => {
  if (!hasValue(value)) return 0;
  return Math.max(0, Math.min(100, Number(value)));
};

const availablePercentText = (usedPercent?: number | null) => {
  if (!hasValue(usedPercent)) return undefined;
  return `${formatNumber(100 - boundedPercent(usedPercent), 1)}% available`;
};

const availableCapacityText = (availableBytes: number, totalBytes?: number | null) => {
  const available = `${formatBytes(availableBytes)} available`;
  return hasValue(totalBytes) && Number(totalBytes) > 0
    ? `${available} / ${formatBytes(Number(totalBytes))} total`
    : available;
};

type TargetHealthState = 'up' | 'degraded' | 'down' | 'unavailable';

const targetHealthStatus = (up?: number | null, total?: number | null): {
  up: number;
  total: number;
  state: TargetHealthState;
} => {
  if (!hasValue(total) || Number(total) <= 0) {
    return { up: 0, total: 0, state: 'unavailable' };
  }
  const totalCount = Math.max(0, Number(total));
  const upCount = hasValue(up) ? Math.max(0, Number(up)) : 0;
  if (upCount >= totalCount) return { up: upCount, total: totalCount, state: 'up' };
  if (upCount > 0) return { up: upCount, total: totalCount, state: 'degraded' };
  return { up: 0, total: totalCount, state: 'down' };
};

const targetHealthLabel = (name: string, health: ReturnType<typeof targetHealthStatus>) => {
  if (health.state === 'unavailable') return `${name} N/A`;
  if (health.state === 'down') return `${name} DOWN`;
  return `${name} ${health.up}/${health.total} UP`;
};

function ResourceCard({ label, value, subtext, tone = 'blue' }: {
  label: string;
  value?: number | null;
  subtext?: string;
  tone?: 'blue' | 'green' | 'purple';
}) {
  const percent = boundedPercent(value);
  return (
    <div className="resource-card">
      <div className="resource-card-header">
        <span className="resource-card-label">{label}</span>
        <strong className="resource-card-value">
          {hasValue(value) ? `${formatNumber(value, 1)}%` : 'N/A'}
        </strong>
      </div>
      <div className="progress-track-bg">
        <div className={`progress-fill-bar ${tone}`} style={{ width: `${percent}%` }} />
      </div>
      {subtext && <span className="resource-subtitle-info">{subtext}</span>}
    </div>
  );
}

